window.COURSE_SEARCH_DATA = [{"id":"c-1-0-0","type":"content","page":1,"pageTitle":"الفك العلوي","section":"لمحة تشريحية","text":"إن الإلمام بتفاصيل العضو الذي تنصبّ فيه اهتمامات طبيب الأسنان أمرٌ حتمي وضروري، وكذلك الإلمام بتفاصيل وتشريح هذا العضو الذي ستستقر فيه الأعمال الصناعية التي ينجزها فني الأسنان.","href":"index.html"},{"id":"c-1-0-1","type":"content","page":1,"pageTitle":"الفك العلوي","section":"لمحة تشريحية","text":"فالعمل الصناعي المخصّص للتوضع في منطقة حيوية سوف يتبادل التأثيرات المختلفة مع ما يحيط بهذه المنطقة.","href":"index.html"},{"id":"c-1-0-2","type":"content","page":1,"pageTitle":"الفك العلوي","section":"لمحة تشريحية","text":"نجاح التعويض السني يبدأ بفهم دقيق للبنية التشريحية المحيطة به.","href":"index.html"},{"id":"c-1-1-0","type":"content","page":1,"pageTitle":"الفك العلوي","section":"الفك العلوي (Maxilla)","text":"يتألف الفك العلوي من اتحاد عظمي الفكّين العلويين الأيمن والأيسر.","href":"index.html#maxillaTitle"},{"id":"c-1-1-1","type":"content","page":1,"pageTitle":"الفك العلوي","section":"الفك العلوي (Maxilla)","text":"يلتقي العظمان على الدرز المتوسط (Median suture) .","href":"index.html#maxillaTitle"},{"id":"c-1-1-2","type":"content","page":1,"pageTitle":"الفك العلوي","section":"الفك العلوي (Maxilla)","text":"يلتقي الناتئان الحنكيان الأفقيان في الخط المتوسط.","href":"index.html#maxillaTitle"},{"id":"c-1-1-3","type":"content","page":1,"pageTitle":"الفك العلوي","section":"الفك العلوي (Maxilla)","text":"يسهمان في تشكيل سقف الفم وقاع الحفرة الأنفية.","href":"index.html#maxillaTitle"},{"id":"c-1-1-4","type":"content","page":1,"pageTitle":"الفك العلوي","section":"الفك العلوي (Maxilla)","text":"تحتوي النواتئ السنخية (Alveolar processes) على الأسناخ المخصّصة لجذور الأسنان.","href":"index.html#maxillaTitle"},{"id":"i-1-0","type":"image","page":1,"pageTitle":"الفك العلوي","section":"الصور والرسوم","text":"رسم تشريحي تعليمي للفك العلوي يوضح الحجاج والناتئ الحنكي والناتئ السنخي المنظر الأنسي والحنكي يركّز على السطح الأنفي، الناتئ الحنكي، الحجاج، والناتئ السنخي.","href":"index.html"},{"id":"i-1-1","type":"image","page":1,"pageTitle":"الفك العلوي","section":"الصور والرسوم","text":"رسم تشريحي تعليمي للفك العلوي يوضح السطح الأمامي والثقبة تحت الحجاج والنتوء الوجني والأسناخ المنظر الأمامي والوحشي يركّز على الثقبة تحت الحجاج، الحفرة النابية، الناتئ الوجني، والأسناخ.","href":"index.html"},{"id":"c-2-0-0","type":"content","page":2,"pageTitle":"الفك السفلي","section":"الفك السفلي (Mandible)","text":"هو عظم مفرد ذو شكل يشبه نعل الفرس، ويتألف من جسم أفقي وشعبتين صاعدتين.","href":"page-02.html"},{"id":"c-2-0-1","type":"content","page":2,"pageTitle":"الفك السفلي","section":"الفك السفلي (Mandible)","text":"الفك السفلي هو العظم المتحرك الوحيد من عظام الجمجمة.","href":"page-02.html"},{"id":"c-2-1-0","type":"content","page":2,"pageTitle":"الفك السفلي","section":"الفكرة التشريحية الأساسية","text":"يتخذ الفك السفلي شكلاً قريباً من نعل الفرس.","href":"page-02.html#structureTitle"},{"id":"c-2-1-1","type":"content","page":2,"pageTitle":"الفك السفلي","section":"الفكرة التشريحية الأساسية","text":"جسم أفقي يحمل الأسنان السفلية والناتئ السنخي.","href":"page-02.html#structureTitle"},{"id":"c-2-1-2","type":"content","page":2,"pageTitle":"الفك السفلي","section":"الفكرة التشريحية الأساسية","text":"شعبتان صاعدتان (Rami) على جانبي الجسم.","href":"page-02.html#structureTitle"},{"id":"c-2-1-3","type":"content","page":2,"pageTitle":"الفك السفلي","section":"الفكرة التشريحية الأساسية","text":"العظم الوحيد المتحرك بين عظام الجمجمة.","href":"page-02.html#structureTitle"},{"id":"c-2-1-4","type":"content","page":2,"pageTitle":"الفك السفلي","section":"الفكرة التشريحية الأساسية","text":"يرتبط بالجمجمة عبر المفصل الفكي الصدغي (TMJ) بواسطة لقمي الفك السفلي.","href":"page-02.html#structureTitle"},{"id":"i-2-0","type":"image","page":2,"pageTitle":"الفك السفلي","section":"الصور والرسوم","text":"رسم تشريحي للفك السفلي من الجانب يوضح الجسم والفرع والناتئين اللقمي والإكليلي المنظر الوحشي يوضح الجسم، الفرع، الناتئ اللقمي، الناتئ الإكليلي، الثقبة الذقنية، والثقبة الفكية.","href":"page-02.html"},{"id":"i-2-1","type":"image","page":2,"pageTitle":"الفك السفلي","section":"الصور والرسوم","text":"رسم تشريحي للفك السفلي من الداخل يوضح الشعبتين والثقبة الفكية والخط المائل الداخلي المنظر الأمامي الداخلي يوضح الشعبتين الصاعدتين، الثقبة الفكية، الخط المائل الداخلي، والحفر الغدية.","href":"page-02.html"},{"id":"i-2-2","type":"image","page":2,"pageTitle":"الفك السفلي","section":"الصور والرسوم","text":"مقطع جانبي يوضح علاقة الفك السفلي والأسنان السفلية بالأضراس العلوية والتجويف الفكي العلاقة السنية والهيكلية يوضح وضع الأسنان السفلية داخل الفك السفلي وعلاقتها بالأسنان العلوية والبنى المجاورة.","href":"page-02.html"},{"id":"c-3-0-0","type":"content","page":3,"pageTitle":"بنية مخاطية الفم","section":"بنية مخاطية الفم (Oral mucosa)","text":"تقع مخاطية الفم في داخل جهاز الهضم، وهي جزء من أجزائه المهمة؛ إذ إن أغلب الأمراض التي تصيب العضوية عامةً وجهاز الهضم بصورة خاصة تتظاهر فيها في مرحلة من مراحلها، وكأنها ميزان العضوية الحساس.","href":"page-03.html"},{"id":"c-3-0-1","type":"content","page":3,"pageTitle":"بنية مخاطية الفم","section":"بنية مخاطية الفم (Oral mucosa)","text":"المخاطية الفموية نسيج حيوي حساس، ودفاعي، ومتجدد باستمرار.","href":"page-03.html"},{"id":"c-3-1-0","type":"content","page":3,"pageTitle":"بنية مخاطية الفم","section":"الدور الحيوي لمخاطية الفم","text":"تمتاز المخاطية الفموية بصفات نوعية تميزها عن غيرها من الأغشية المخاطية، فهي تصمد لتأثير التخريش الآلي والحيوي، وقد تُعَدّ أحد حصون البدن الأولى في الكفاح ضد العوامل الخارجية؛ وذلك بفضل خلاياها المختلفة واللعاب الذي تفرزه غددها.","href":"page-03.html#mucosaRoleTitle"},{"id":"c-3-1-1","type":"content","page":3,"pageTitle":"بنية مخاطية الفم","section":"الدور الحيوي لمخاطية الفم","text":"كذلك للغشاء المخاطي الفموي خصائص نوعية في هندسته البنيوية، ونظام تقرنه، وتوزع بعض المستقبلات في هيولاه، عدا عن قدرته الهائلة على التندب والترميم.","href":"page-03.html#mucosaRoleTitle"},{"id":"c-3-1-2","type":"content","page":3,"pageTitle":"بنية مخاطية الفم","section":"الدور الحيوي لمخاطية الفم","text":"تتحمل المخاطية تأثير الاحتكاك والتخريش الآلي المتكرر داخل الفم.","href":"page-03.html#mucosaRoleTitle"},{"id":"c-3-1-3","type":"content","page":3,"pageTitle":"بنية مخاطية الفم","section":"الدور الحيوي لمخاطية الفم","text":"تسهم خلايا المخاطية واللعاب في الحماية من العوامل الخارجية.","href":"page-03.html#mucosaRoleTitle"},{"id":"c-3-1-4","type":"content","page":3,"pageTitle":"بنية مخاطية الفم","section":"الدور الحيوي لمخاطية الفم","text":"تختلف بنيتها ونظام تقرنها بحسب الموقع والوظيفة داخل جوف الفم.","href":"page-03.html#mucosaRoleTitle"},{"id":"c-3-1-5","type":"content","page":3,"pageTitle":"بنية مخاطية الفم","section":"الدور الحيوي لمخاطية الفم","text":"تتميز بقدرة كبيرة على التعافي وإصلاح الأنسجة بعد الأذية.","href":"page-03.html#mucosaRoleTitle"},{"id":"c-3-2-0","type":"content","page":3,"pageTitle":"بنية مخاطية الفم","section":"الشفتان (Lips)","text":"الشفتان عبارة عن نسيج عضلي متحرك يشكّل غطاء الأسنان، وهما متصلتان مع بعضهما بعضاً عند الإطباق بالخط الشفوي، وهو بطول 5 سم وسطياً؛ قد يقل عند بعض الأشخاص وقد يزيد عند بعضهم الآخر، ونهايتا هذا الخط تشكّلان صوارَي الفم.","href":"page-03.html#lipsTitle"},{"id":"c-3-2-1","type":"content","page":3,"pageTitle":"بنية مخاطية الفم","section":"الشفتان (Lips)","text":"تحوي غدداً عرقية، وجذور الأشعار، وغدداً دهنية.","href":"page-03.html#lipsTitle"},{"id":"c-3-2-2","type":"content","page":3,"pageTitle":"بنية مخاطية الفم","section":"الشفتان (Lips)","text":"تقع بين الطبقتين الخارجية والداخلية، وتُدعى أيضاً المنطقة الحمراء، وتحوي غدداً دهنية.","href":"page-03.html#lipsTitle"},{"id":"c-3-2-3","type":"content","page":3,"pageTitle":"بنية مخاطية الفم","section":"الشفتان (Lips)","text":"تشكّل السطح الداخلي للشفة المواجه لجوف الفم.","href":"page-03.html#lipsTitle"},{"id":"i-3-0","type":"image","page":3,"pageTitle":"بنية مخاطية الفم","section":"الصور والرسوم","text":"صورة تشريحية للشفتين تُظهر قوس كيوبيد والنثرة والحافة الحمراء وحديبتَي الشفة وصوارَي الفم معالم الشفتين الظاهرة في الصورة قوس كيوبيد، النثرة، الحافة الحمراء، الحديبات، وصوارا الفم.","href":"page-03.html"},{"id":"c-4-0-0","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"الخد وسقف الفم واللسان","text":"تستكمل هذه الصفحة دراسة مخاطية الفم من خلال الغشاء المخاطي المبطن للخد، وبنية الحنك الصلب والحنك الرخو، ثم اللسان وحليماته وبراعم الذوق.","href":"page-04.html"},{"id":"c-4-0-1","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"الخد وسقف الفم واللسان","text":"تتكامل البنى الرخوة داخل جوف الفم في المضغ والبلع والإحساس بالذوق.","href":"page-04.html"},{"id":"c-4-1-0","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"الخد وسقف الفم","text":"هو استمرار للغشاء المخاطي الشفوي نفسه، وله البنية نفسها.","href":"page-04.html#cheekPalateTitle"},{"id":"c-4-1-1","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"الخد وسقف الفم","text":"يشكّل سقف الفم الحاجز الفاصل بين حفرة الفم والحفرتين الأنفيتين.","href":"page-04.html#cheekPalateTitle"},{"id":"c-4-1-2","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"الخد وسقف الفم","text":"هي الجزء الأمامي من قبة الحنك، ويدخل في تشكيلها أربعة عظام، وتُغطى بنسيج كثيف.","href":"page-04.html#cheekPalateTitle"},{"id":"c-4-1-3","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"الخد وسقف الفم","text":"هي الجزء الخلفي من قبة الحنك، وهي حاجز سائب يتحرك حركة تشبه الشراع، ويمتد للخلف نحو البلعوم ليقسمه إلى بلعوم أنفي وبلعوم فموي.","href":"page-04.html#cheekPalateTitle"},{"id":"c-4-1-4","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"الخد وسقف الفم","text":"تنتهي قبة الحنك الرخوة ببروز يتدلى نحو الأسفل يسمى اللهاة . وتشكل الحزم العضلية المخططة الهيكل الأساسي لشراع الحنك، وتتقلص هذه العضلات أثناء البلع، فتشد شراع الحنك إلى الأعلى والخلف، فيُغلق فوهة البلعوم الأنفي.","href":"page-04.html#cheekPalateTitle"},{"id":"c-4-3-0","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"اللسان (Tongue)","text":"اللسان عضو عضلي يشغل قاع الفم، ويتكون من 17 عضلة، وهو مستور بغشاء مخاطي ملتصق بشدة بما تحته.","href":"page-04.html#tongueTitle"},{"id":"c-4-3-1","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"اللسان (Tongue)","text":"سطح اللسان العلوي محدب من الأمام للخلف، بينما السطح السفلي مغطى بغشاء مخاطي رقيق. ويشاهد على الوجه السفلي لجام اللسان، وهو طية مخاطية تمتد من منتصف اللسان إلى عظم الفك السفلي، ويتمادى الغشاء المخاطي لسطح اللسان السفلي مع الغشاء المخاطي لقاع الفم.","href":"page-04.html#tongueTitle"},{"id":"c-4-3-2","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"اللسان (Tongue)","text":"يحمل بروزات صغيرة تسمى الحليمات اللسانية.","href":"page-04.html#tongueTitle"},{"id":"c-4-3-3","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"اللسان (Tongue)","text":"أملس ولا تظهر عليه الحليمات اللسانية.","href":"page-04.html#tongueTitle"},{"id":"c-4-3-4","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"اللسان (Tongue)","text":"طية مخاطية وسطية تصل اللسان بعظم الفك السفلي.","href":"page-04.html#tongueTitle"},{"id":"c-4-3-5","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"اللسان (Tongue)","text":"تستمر مخاطية السطح السفلي مع مخاطية قاع الفم.","href":"page-04.html#tongueTitle"},{"id":"c-4-4-0","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"أنواع الحليمات وبراعم الذوق","text":"أحد الأنواع الأربعة للحليمات الدقيقة الموجودة على ظهر اللسان.","href":"page-04.html#papillaeTitle"},{"id":"c-4-4-1","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"أنواع الحليمات وبراعم الذوق","text":"تُذكر في المصدر ضمن الأنواع الرئيسية للحليمات اللسانية.","href":"page-04.html#papillaeTitle"},{"id":"c-4-4-2","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"أنواع الحليمات وبراعم الذوق","text":"توجد ضمن مجموعات الحليمات اللسانية ذات العلاقة بالإحساس الذوقي.","href":"page-04.html#papillaeTitle"},{"id":"c-4-4-3","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"أنواع الحليمات وبراعم الذوق","text":"تقع عند الحد الفاصل بين الثلث الخلفي والثلثين الأماميين للسان.","href":"page-04.html#papillaeTitle"},{"id":"c-4-4-4","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"أنواع الحليمات وبراعم الذوق","text":"زيتونات الذوق أو براعم الذوق هي أجهزة انتهائية حسية تفيد في التحليل الذوقي. تتوضع في بشرة الحليمات اللسانية جميعها عدا الحليمات الخيطية، وتكثر في بشرة الحليمات الكأسية، ويوجد في كل منها نحو 40–50 بصلة ذوق.","href":"page-04.html#papillaeTitle"},{"id":"c-4-5-3","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"مواضع الإحساس بالمذاقات","text":"المناطق الجانبية الخلفية.","href":"page-04.html#tasteTitle"},{"id":"c-4-5-4","type":"content","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"مواضع الإحساس بالمذاقات","text":"يعرض هذا القسم التوزع التقليدي للمذاقات كما ورد في الصفحة الأصلية.","href":"page-04.html#tasteTitle"},{"id":"i-4-0","type":"image","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"الصور والرسوم","text":"رسم عربي لجوف الفم يوضح الشفة واللثة والحنك الصلب وشراع الحنك واللوزة الحنكية واللهاة واللسان والأسنان معالم جوف الفم الشفة، اللثة، الحنك الصلب، شراع الحنك، اللوزة الحنكية، اللهاة، اللسان، الأسنان، القواطع، الأنياب والضواحك.","href":"page-04.html"},{"id":"i-4-1","type":"image","page":4,"pageTitle":"الخد وسقف الفم واللسان","section":"الصور والرسوم","text":"رسم لأقسام اللسان يوضح أقصى اللسان ووسط اللسان وطرفه ورأسه وحافته أقسام اللسان الظاهرة في المصدر أقصى اللسان، وسط اللسان، طرف اللسان، رأس اللسان، حافة اللسان.","href":"page-04.html"},{"id":"c-5-0-0","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"الغدد اللعابية واللعاب","text":"الغدد اللعابية أعضاء خارجية الإفراز تفتح أقنيتها في جوف الفم، وتنتج اللعاب الذي يسهّل المضغ والبلع ويسهم في هضم بعض العناصر.","href":"page-05.html"},{"id":"c-5-0-1","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"الغدد اللعابية واللعاب","text":"أكبر مساهمة في الإفراز اللعابي الوسطي تأتي من الغدد تحت الفك بحسب النسب الواردة في المصدر.","href":"page-05.html"},{"id":"c-5-1-0","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"لماذا يحتاج الفم إلى اللعاب؟","text":"يساعد اللعاب في تهيئة الطعام داخل الفم وتحريكه أثناء المضغ.","href":"page-05.html#rolesTitle"},{"id":"c-5-1-1","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"لماذا يحتاج الفم إلى اللعاب؟","text":"يسهم في ترطيب اللقمة وتسهيل انتقالها خلال عملية البلع.","href":"page-05.html#rolesTitle"},{"id":"c-5-1-2","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"لماذا يحتاج الفم إلى اللعاب؟","text":"يشارك اللعاب في بدء هضم بعض مكونات الطعام كما ورد في المصدر.","href":"page-05.html#rolesTitle"},{"id":"c-5-2-0","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"الغدد اللعابية الكبرى وقنواتها","text":"يتوضع قسمها السطحي أمام الأذن الخارجية، بينما يملأ قسمها العميق الحفرة الفكية الخلفية.","href":"page-05.html#majorGlandsTitle"},{"id":"c-5-2-1","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"الغدد اللعابية الكبرى وقنواتها","text":"يتوضع قسمها الأكبر في القسم تحت الفكي، خلف وأسفل العضلة الضرسية اللامية.","href":"page-05.html#majorGlandsTitle"},{"id":"c-5-2-2","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"الغدد اللعابية الكبرى وقنواتها","text":"تتوضع في أرض الفم ضمن الطية تحت اللسانية.","href":"page-05.html#majorGlandsTitle"},{"id":"c-5-3-1","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"مواضع الغدد اللعابية الكبرى","text":"أمام الأذن الخارجية، مع امتداد عميق في الحفرة الفكية الخلفية.","href":"page-05.html#diagramTitle"},{"id":"c-5-3-2","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"مواضع الغدد اللعابية الكبرى","text":"خلف وأسفل العضلة الضرسية اللامية.","href":"page-05.html#diagramTitle"},{"id":"c-5-3-3","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"مواضع الغدد اللعابية الكبرى","text":"في أرض الفم ضمن الطية تحت اللسانية.","href":"page-05.html#diagramTitle"},{"id":"c-5-4-0","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"الغدد اللعابية الصغرى","text":"توجد إلى جانب الغدد الكبرى، وتنتشر في مناطق عديدة من جوف الفم.","href":"page-05.html#minorTitle"},{"id":"c-5-4-1","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"الغدد اللعابية الصغرى","text":"تشير الصفحة الأصلية إلى دور للغدد اللعابية في استقلاب اليود، وإلى احتوائها على عوامل مرتبطة بالنمو ومادة تؤثر في استقلاب الكالسيوم.","href":"page-05.html#minorTitle"},{"id":"c-5-5-0","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"مساهمة الغدد في مجموع اللعاب","text":"تمثل النسبة الأكبر من الإفراز اللعابي الوسطي.","href":"page-05.html#salivaTitle"},{"id":"c-5-5-1","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"مساهمة الغدد في مجموع اللعاب","text":"تأتي في المرتبة الثانية بحسب النسب المذكورة.","href":"page-05.html#salivaTitle"},{"id":"c-5-5-2","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"مساهمة الغدد في مجموع اللعاب","text":"تسهم بنسبة أصغر من مجموع الإفراز.","href":"page-05.html#salivaTitle"},{"id":"c-5-6-0","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"لماذا يختلف تركيب اللعاب؟","text":"يختلف تركيب اللعاب كثيراً من شخص إلى آخر.","href":"page-05.html#variationTitle"},{"id":"c-5-6-1","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"لماذا يختلف تركيب اللعاب؟","text":"يختلف الإفراز من غدة لعابية إلى أخرى.","href":"page-05.html#variationTitle"},{"id":"c-5-6-2","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"لماذا يختلف تركيب اللعاب؟","text":"تؤثر طبيعة المنبه وشدته في الإفراز وتركيبه.","href":"page-05.html#variationTitle"},{"id":"c-5-6-3","type":"content","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"لماذا يختلف تركيب اللعاب؟","text":"لا تكون النسب المئوية مفيدة إن لم تُذكر الظروف التي جُمع فيها اللعاب.","href":"page-05.html#variationTitle"},{"id":"i-5-0","type":"image","page":5,"pageTitle":"الغدد اللعابية واللعاب","section":"الصور والرسوم","text":"رسم جانبي للرأس يوضح الغدة النكفية والغدة تحت الفك والغدة تحت اللسان واللسان الخريطة التشريحية في المصدر توضح موضع الغدة النكفية، وتحت الفك، وتحت اللسان بالنسبة إلى اللسان وجوف الفم.","href":"page-05.html"},{"id":"c-6-0-0","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"الأسنان المؤقتة والأسنان الدائمة","text":"يبزغ في الفم مجموعتان من الأسنان، تتناسب كل واحدة منهما مع المتطلبات الوظيفية للإنسان في مرحلتها العمرية. تبدأ الأسنان المؤقتة عادةً بالظهور قرب الشهر السادس، ثم تبدأ الأسنان الدائمة بالظهور قرب السنة السادسة.","href":"page-06.html"},{"id":"c-6-0-1","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"الأسنان المؤقتة والأسنان الدائمة","text":"قرب عمر ست سنوات تبدأ مرحلة تبدل الأسنان، وقد تبقى سن مؤقتة إذا غاب خلفها البديل الدائم أو لم يبزغ.","href":"page-06.html"},{"id":"c-6-1-0","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"من الأسنان المؤقتة إلى الدائمة","text":"تبدأ بالظهور نحو الشهر السادس، وتستمر عادةً حتى مرحلة تبدل الأسنان. يوجد في كل فك عشر أسنان، وفي كل جانب خمسة.","href":"page-06.html#dentitionsTitle"},{"id":"c-6-1-6","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"من الأسنان المؤقتة إلى الدائمة","text":"تبدأ بالظهور قرب السنة السادسة من العمر، وتضم في كل فك ست عشرة سناً وفي كل جانب ثمانية أسنان.","href":"page-06.html#dentitionsTitle"},{"id":"c-6-1-12","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"من الأسنان المؤقتة إلى الدائمة","text":"قد تبقى السن المؤقتة مدة أطول إذا فُقدت السن الدائمة البديلة أو لم تبزغ لأسباب مختلفة.","href":"page-06.html#dentitionsTitle"},{"id":"c-6-3-0","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"مواعيد البزوغ والسقوط","text":"يختلف توقيت بزوغ الأسنان اللبنية والدائمة إلى درجة كبيرة، ويُعد تقدم أو تأخر البزوغ نحو ستة أشهر عن الوقت المعتاد أمراً طبيعياً لدى طفل معين.","href":"page-06.html#primaryScheduleTitle"},{"id":"c-6-4-0","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"أهمية المحافظة على الأسنان اللبنية","text":"تعد المحافظة على الأسنان اللبنية حتى سقوطها الطبيعي أمراً ضرورياً؛ فهي تحفظ المكان المخصص للسن الدائمة التي ستخلفها.","href":"page-06.html#preservationTitle"},{"id":"c-6-4-1","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"أهمية المحافظة على الأسنان اللبنية","text":"قد يؤدي قلع السن المؤقتة مبكراً إلى انشغال المسافة المخصصة للسن الدائمة وحدوث اضطراب في الإطباق يستدعي التقويم.","href":"page-06.html#preservationTitle"},{"id":"c-6-4-2","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"أهمية المحافظة على الأسنان اللبنية","text":"عند الاضطرار إلى قلع سن لبنية مبكراً قد يلزم وضع جهاز يحافظ على المسافة المخصصة للسن الدائمة.","href":"page-06.html#preservationTitle"},{"id":"c-6-5-0","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"عوارض بزوغ الأسنان والتدبير المذكور في المصدر","text":"بزوغ الأسنان عملية فيزيولوجية طبيعية، ولا يثبت النص دوراً مباشراً للبزوغ في الاضطرابات العامة السابقة.","href":"page-06.html#teethingTitle"},{"id":"c-6-5-1","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"عوارض بزوغ الأسنان والتدبير المذكور في المصدر","text":"قد تتزامن هذه الأعراض مع مرحلة يضع فيها الطفل أشياء مختلفة في فمه لتخفيف الانزعاج، مما قد ينقل الجراثيم ويؤدي إلى اضطرابات هضمية؛ لذلك قد تكون الأعراض العامة مصادفة زمنية.","href":"page-06.html#teethingTitle"},{"id":"c-6-5-2","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"عوارض بزوغ الأسنان والتدبير المذكور في المصدر","text":"قد يرافق البزوغ ألم عابر يزول خلال أيام قليلة، ولا يُنصح باستئصال النسيج المغطي للسن إلا عند الضرورة.","href":"page-06.html#teethingTitle"},{"id":"c-6-5-3","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"عوارض بزوغ الأسنان والتدبير المذكور في المصدر","text":"يذكر المصدر إمكان استخدام مخدر موضعي غير مخرش عدة مرات يومياً، قبل الطعام وقبل النوم، وفق توجيه مهني مناسب.","href":"page-06.html#teethingTitle"},{"id":"c-6-5-4","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"عوارض بزوغ الأسنان والتدبير المذكور في المصدر","text":"يمكن تقديم حلقة تسنين باردة بالثلاجة لتخفيف الانزعاج، مع تجنب تشجيع الطفل على مص الإصبع.","href":"page-06.html#teethingTitle"},{"id":"c-6-7-0","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"شذوذات عدد الأسنان وشكلها وبنيتها","text":"يُعتقد أنها تنتج عن انحرافات في المرحلة الأولية لدورة حياة السن، مع احتمال وجود ميل وراثي. ترد بنسبة 1–9% في الأسنان الدائمة، وتكون أقل شيوعاً في الأسنان المؤقتة وأكثر انتشاراً لدى الذكور.","href":"page-06.html#developmentTitle"},{"id":"c-6-7-1","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"شذوذات عدد الأسنان وشكلها وبنيتها","text":"يمكن أن تظهر في أي موضع، وأكثرها مصادفة السن الأنسيّة بين الثنايا العلوية، وتكون غالباً صغيرة مخروطية ذات جذر قصير، وقد تكون مفردة أو مزدوجة.","href":"page-06.html#developmentTitle"},{"id":"c-6-7-2","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"شذوذات عدد الأسنان وشكلها وبنيتها","text":"قد تؤخر بزوغ الأسنان الخلفية أو تمنعه أو تغير مسار البزوغ؛ لذلك يفيد الكشف المبكر وقلعها بعد بزوغها، أو قبل ذلك عند وجود اختلاط.","href":"page-06.html#developmentTitle"},{"id":"c-6-7-3","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"شذوذات عدد الأسنان وشكلها وبنيتها","text":"يكون عادةً وراثياً، وقد يكون غياباً كاملاً أو جزئياً.","href":"page-06.html#developmentTitle"},{"id":"c-6-7-4","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"شذوذات عدد الأسنان وشكلها وبنيتها","text":"قد تنجم عن آفات مرضية أو أسباب وراثية أو رضوض تصيب المنطقة.","href":"page-06.html#developmentTitle"},{"id":"c-6-7-5","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"شذوذات عدد الأسنان وشكلها وبنيتها","text":"يذكر المصدر سوء تصنيع الميناء، الذي قد يكون موضعياً أو واسعاً، وقصور تصنيع الميناء، وسوء تصنيع العاج.","href":"page-06.html#developmentTitle"},{"id":"c-6-7-6","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"شذوذات عدد الأسنان وشكلها وبنيتها","text":"يشكل التتراسكلين مركباً مع شوارد الكلس المترسبة على سطوح بلورات الهيدروكسي أباتيت، فيتداخل مع تمعدن نسج السن الصلبة.","href":"page-06.html#developmentTitle"},{"id":"c-6-7-7","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"شذوذات عدد الأسنان وشكلها وبنيتها","text":"تعتمد شدة الاصطباغ على المقدار الدوائي، ويتحدد الجزء المتلون بمرحلة تطور السن ووقت تناول التتراسكلين.","href":"page-06.html#developmentTitle"},{"id":"c-6-8-0","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"السن الولادي، التسنن، وأكياس البزوغ","text":"سن تكون موجودة في الفم منذ الولادة، لكنها لا تُعد سناً زائدة. تظهر غالباً في منطقة القواطع السفلية وتتميز بالحركة بسبب عدم اكتمال نمو الجذر.","href":"page-06.html#eruptionDisordersTitle"},{"id":"c-6-8-1","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"السن الولادي، التسنن، وأكياس البزوغ","text":"قد يرافق البزوغ انزعاج موضعي واضطراب في النوم. يذكر المصدر إمكان التخفيف موضعياً بمستحضرات مناسبة، كما أن عض جسم قاسٍ قد يساعد على تخفيف الانزعاج.","href":"page-06.html#eruptionDisordersTitle"},{"id":"c-6-8-2","type":"content","page":6,"pageTitle":"الأسنان والبزوغ","section":"السن الولادي، التسنن، وأكياس البزوغ","text":"هي تجمع سائل أو دم داخل المسافة الجرابية المحيطة بالسن، وقد يعطي تجمع الدم لوناً مائلاً إلى الأزرق.","href":"page-06.html#eruptionDisordersTitle"},{"id":"i-6-0","type":"image","page":6,"pageTitle":"الأسنان والبزوغ","section":"الصور والرسوم","text":"مخطط مأخوذ من المصدر يوضح أوقات بزوغ الأسنان المؤقتة والدائمة في الفكين المخطط الوارد في الصفحة الأصلية يعرض ترتيباً عاماً لمواعيد بزوغ الأسنان اللبنية والدائمة في الفكين العلوي والسفلي.","href":"page-06.html"},{"id":"c-7-0-0","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الميناء، العاج، الملاط، واللب","text":"تتألف السن من أنسجة مختلفة تؤدي معاً وظيفة الحماية والدعم والحس. تغطي الميناء التاج، ويشكّل العاج القسم الأكبر من السن، بينما يغطي الملاط الجذر، ويشكّل اللب النسيج الحي المركزي الحساس داخل السن.","href":"page-07.html"},{"id":"c-7-0-1","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الميناء، العاج، الملاط، واللب","text":"التاج يُغطى بالميناء، الجذر يُغطى بالملاط، وبينهما العاج، وفي المركز اللب.","href":"page-07.html"},{"id":"c-7-1-0","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"ملخص الأنسجة السنية","text":"طبقة خارجية تغطي التاج وتحميه من المؤثرات الميكانيكية والحرارية والكيميائية.","href":"page-07.html#overviewTissuesTitle"},{"id":"c-7-1-1","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"ملخص الأنسجة السنية","text":"يشكل أساس السن والكتلة المركزية لها، وهو أقل صلابة من الميناء وأكثر صلابة من العظم.","href":"page-07.html#overviewTissuesTitle"},{"id":"c-7-1-2","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"ملخص الأنسجة السنية","text":"يغلف الجذر فقط، ويشبه في تركيبه إلى حد بعيد تركيب العظم.","href":"page-07.html#overviewTissuesTitle"},{"id":"c-7-1-3","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"ملخص الأنسجة السنية","text":"النسيج الحي داخل السن، مكوّن من ألياف عصبية وأوعية شريانية ووريدية.","href":"page-07.html#overviewTissuesTitle"},{"id":"c-7-2-0","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الميناء","text":"الميناء هي الطبقة الخارجية المغطية للسن، وتشكل غطاءً متيناً يقاوم المؤثرات الخارجية الميكانيكية والحرارية والكيميائية.","href":"page-07.html#enamelTitle"},{"id":"c-7-2-1","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الميناء","text":"يختلف سمكها بحسب المناطق المختلفة للسن وحسب نوع الأسنان، ويتراوح تقريباً بين 0.01 مم عند الأعناق و 2 مم عند ذرى الحدبات، ولا تزيد في بروزات الأرحاء على 3 مم .","href":"page-07.html#enamelTitle"},{"id":"c-7-2-2","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الميناء","text":"يتدرج لون الميناء بين الأبيض المصفر والأبيض الرمادي، ويُعزى اختلاف اللون إلى شفافية الميناء ودرجة تجانسها.","href":"page-07.html#enamelTitle"},{"id":"c-7-2-3","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الميناء","text":"الأسنان المصفرة تملك ميناء رقيقة نسبياً يشف من خلالها لون العاج الأصفر، بينما تظهر الأسنان الرمادية أكثر عتامـة.","href":"page-07.html#enamelTitle"},{"id":"c-7-2-4","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الميناء","text":"تبدو منطقة العنق أكثر اصفراراً، بينما تميل الأقسام القاطعة إلى الأزرق قليلاً بسبب رقة الحد القاطع.","href":"page-07.html#enamelTitle"},{"id":"c-7-2-5","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الميناء","text":"تُعد من أقسى أنسجة الجسم، وتُقارن صلابتها بصلابة الكوارتز وفق الوصف المذكور في المصدر.","href":"page-07.html#enamelTitle"},{"id":"c-7-2-6","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الميناء","text":"تضم فوسفات الكالسيوم (هيدروكسي أباتيت) وفوسفات الكالسيوم وفلورور الكالسيوم.","href":"page-07.html#enamelTitle"},{"id":"c-7-2-7","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الميناء","text":"تمثل النسبة الصغيرة غير المعدنية من بنية الميناء.","href":"page-07.html#enamelTitle"},{"id":"c-7-2-8","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الميناء","text":"تتكون طبقة الميناء نسيجياً من المؤاشير المينائية والمادة اللاصقة بينها، حيث تتخذ المؤاشير اتجاهات شعاعية وتتجاوز سماكة الميناء.","href":"page-07.html#enamelTitle"},{"id":"c-7-3-0","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"العاج","text":"العاج يشكل أساس السن ومصدر قوتها، ويمثل الكتلة المركزية لأنسجة السن الصلبة.","href":"page-07.html#dentinTitle"},{"id":"c-7-3-1","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"العاج","text":"لونه الطبيعي عند الشباب بين الأبيض والأصفر الفاتح، ويزداد اصفراراً مع التقدم في العمر. وقد يتلون بألوان مختلفة عند تماسّه مع سوائل الفم أو الأدوية الموضعية أو مواد الحشو.","href":"page-07.html#dentinTitle"},{"id":"c-7-3-2","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"العاج","text":"العاج أقل صلابة من الميناء وأكثر صلابة من العظم.","href":"page-07.html#dentinTitle"},{"id":"c-7-3-4","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"العاج","text":"أهمها فوسفات الكالسيوم وكربونات الكالسيوم وكربونات المغنزيوم.","href":"page-07.html#dentinTitle"},{"id":"c-7-3-7","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"العاج","text":"يتألف العاج من أنابيب عاجية صغيرة تمتد من المركز نحو المحيط، وتحتوي أليافاً شبه عصبية تنقل الإحساسات الألمية إلى اللب السني، وتسمى ألياف توماز.","href":"page-07.html#dentinTitle"},{"id":"c-7-4-0","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الملاط","text":"الملاط يغلف الجذور فقط وينتهي عند العنق، ويلتقي مع الميناء في هذه المنطقة.","href":"page-07.html#cementumTitle"},{"id":"c-7-4-1","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الملاط","text":"قد يكون التقاء الميناء بالملاط بإحدى ثلاث حالات: أن يغطي الملاط الميناء بمسافة قصيرة، أو أن تغطي الميناء الملاط، أو أن يكون بينهما فراغ بسيط ينكشف فيه العاج.","href":"page-07.html#cementumTitle"},{"id":"c-7-4-2","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الملاط","text":"يكشف هذا سبب الألم عند محاولة حكّ السن بأداة عند منطقة العنق.","href":"page-07.html#cementumTitle"},{"id":"c-7-4-3","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"الملاط","text":"يشبه تركيب الملاط إلى حد بعيد تركيب العظم بحسب النص المرفق.","href":"page-07.html#cementumTitle"},{"id":"c-7-5-0","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"اللب","text":"اللب هو النسيج الحي داخل السن، ويتألف من ألياف عصبية وأوعية شريانية ووريدية.","href":"page-07.html#pulpTitle"},{"id":"c-7-5-1","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"اللب","text":"وظيفة اللب إعطاء الحساسية للسن، كما يتشكل فيه نوعان من العاج:","href":"page-07.html#pulpTitle"},{"id":"c-7-5-2","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"اللب","text":"يتشكل بشكل طبيعي مع الزمن على جدران اللب، مؤدياً إلى زيادة سماكة العاج.","href":"page-07.html#pulpTitle"},{"id":"c-7-5-3","type":"content","page":7,"pageTitle":"بنية الأسنان","section":"اللب","text":"يتشكل كرد فعل دفاعي تجاه العوامل المؤذية الخارجية مثل نخر السن أو التهيج الحراري، فيدفع اللب إلى التراجع مبتعداً عن الخطر.","href":"page-07.html#pulpTitle"},{"id":"i-7-0","type":"image","page":7,"pageTitle":"بنية الأسنان","section":"الصور والرسوم","text":"رسم مقطعي في سن يوضح الميناء والعاج واللب والجذر والعظم واللثة الصورة الأصلية المقتطعة من المصدر توضح تموضع العاج بالنسبة إلى الميناء واللب وعظم الفك.","href":"page-07.html"},{"id":"i-7-1","type":"image","page":7,"pageTitle":"بنية الأسنان","section":"الصور والرسوم","text":"رسم تخطيطي صغير يوضح الأنابيب العاجية وألياف توماز مخطط داعم يبين الأنابيب العاجية والألياف الممتدة ضمنها.","href":"page-07.html"},{"id":"i-7-2","type":"image","page":7,"pageTitle":"بنية الأسنان","section":"الصور والرسوم","text":"رسم تخطيطي لسن يوضح الميناء والعاج واللب واللثة والعظم السنخي والملاط السن ضمن النسج الداعمة يوضح أن الملاط يغلف الجذر ويتصل بالميناء عند العنق بطرائق مختلفة.","href":"page-07.html"},{"id":"i-7-3","type":"image","page":7,"pageTitle":"بنية الأسنان","section":"الصور والرسوم","text":"مقطع طولي أمامي للسن يوضح الميناء والعاج واللب والعصب والرباط اللثوي مقطع أمامي لأجزاء السن يوضح تموضع اللب السني بالنسبة إلى العاج والعصب وبقية البنى.","href":"page-07.html"},{"id":"c-8-0-0","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"جميع النسج الداعمة للسن","text":"يقصد بالنسج الداعمة للسن أو (Periodont) جميع العناصر التي تثبت السن وتحافظ على وجودها الوظيفي، وتشمل الملاط و النسج الداعمة المحيطة به، وفي هذه الصفحة نركز على: اللثة و الرباط السنيخي السني و العظم السنخي .","href":"page-08.html"},{"id":"c-8-0-1","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"جميع النسج الداعمة للسن","text":"كل عنصر من النسج المحيطة يؤدي وظيفة دعم وتثبيت وحماية، وأي خلل ممتد فيها ينعكس على ثبات السن وبقائها.","href":"page-08.html"},{"id":"c-8-1-0","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"ما النسج المحيطة بالسن؟","text":"النسج الداعمة للسن: هي جميع النسج الداعمة للسن وتشمل الملاط والأنسجة والعظم والرباط واللثة.","href":"page-08.html#periodontTitle"},{"id":"c-8-1-1","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"ما النسج المحيطة بالسن؟","text":"أمراض النسج الداعمة للسن: هي جميع الحالات السريرية أو التدرج المرضي من النوع الالتهابي والمتخرب الذي يشمل جميع العناصر الداعمة للسن، وقد يتميز سريرياً بالتهاب اللثة وتشكل الخراجات وتآكل الأسنان وتقلقل الأسنان وسقوطها.","href":"page-08.html#periodontTitle"},{"id":"c-8-1-2","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"ما النسج المحيطة بالسن؟","text":"يكشف هذا الالتهاب عند ظهور عرض أو مجموعة أعراض، مثل احمرار اللثة وتورمها وتقرحها.","href":"page-08.html#periodontTitle"},{"id":"c-8-1-3","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"ما النسج المحيطة بالسن؟","text":"يكشف بإدخال المسبار حول السن بعمق يزيد عن 3 ملم ، وهو دليل على إصابة مرضية أعمق في النسج الداعمة.","href":"page-08.html#periodontTitle"},{"id":"c-8-2-0","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"اللثة","text":"اللثة هي الجزء الأساسي من النسيج المحيط بالسن، وتتألف من نسيج حي مكوّن من نسيج ضام ورابطة لثوية.","href":"page-08.html#gingivaTitle"},{"id":"c-8-2-1","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"اللثة","text":"تغلف اللثة العظم السنخي وتحيط بأعناق الأسنان، وتتكون من عدة مناطق رئيسية:","href":"page-08.html#gingivaTitle"},{"id":"c-8-2-2","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"اللثة","text":"عرضها نحو 1 ملم ، تغطي أعناق الأسنان وتنطبق عليها بشكل كبير، ويمكن إدخال آلية ذات رأس كليل بين السن واللثة لمسافة 0.5–1 ملم ، وهذا ما يسمى الميزاب اللثوي. وإذا زادت المسافة فنكون أمام حالة مرضية تسمى الجيب السني.","href":"page-08.html#gingivaTitle"},{"id":"c-8-2-3","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"اللثة","text":"هي بروزات أو حليمات صغيرة تتوضع بين الأسنان وتشكل المسافة بين السنية.","href":"page-08.html#gingivaTitle"},{"id":"c-8-2-4","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"اللثة","text":"تقع بين اللثة الحفافية وبين الغشاء المخاطي الفموي.","href":"page-08.html#gingivaTitle"},{"id":"c-8-3-0","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"الرباط السنيخي السني","text":"يشكل الرباط السنيخي السني أداة الربط بين السن والعظم السنخي، ويتشكل من ألياف كثيفة ترتبط بالعظم السنخي من جهة وبملاط السن من جهة أخرى.","href":"page-08.html#ligamentTitle"},{"id":"c-8-3-1","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"الرباط السنيخي السني","text":"يحتوي الرباط على شبكة من الشرايين والأوردة والألياف العصبية؛ لذلك إذا حدث احتقان فيه نتيجة عالٍ على مستوى الإطباق أو نتيجة التهاب ناتج عن الجراثيم الوافدة من الذروة، فإن زيادة السوائل الدموية في هذه المنطقة قد تدفع السن نحو الخارج فتبدو أعلى على مستوى الإطباق، ويظهر ألم عند الضغط.","href":"page-08.html#ligamentTitle"},{"id":"c-8-4-0","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"العظم السنخي","text":"العظم السنخي هو العظم الذي تنغرس فيه الأسنان، ويتألف من صفيحة عظمية دهليزية وأخرى لسانية وحواجز سنخية بين سنية.","href":"page-08.html#boneTitle"},{"id":"c-8-4-1","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"العظم السنخي","text":"وهو عظم إسفنجي، لذلك يسهل كسره أو رضّه، خاصة أثناء القلع الصعب. ويرتبط وجوده بوجود الأسنان؛ فعند قلع الأسنان يمتص هذا العظم ويزول.","href":"page-08.html#boneTitle"},{"id":"c-8-4-2","type":"content","page":8,"pageTitle":"النسج المحيطة بالسن","section":"العظم السنخي","text":"يمتاز بأنه أضعف من بقية النسج حول السنية، ولذلك فإن كثيراً من الأمراض اللثوية تترافق بالامتصاص العظمي أو التراجع العظمي (رعل).","href":"page-08.html#boneTitle"},{"id":"i-8-0","type":"image","page":8,"pageTitle":"النسج المحيطة بالسن","section":"الصور والرسوم","text":"رسم تخطيطي يبين الميناء والعاج واللب والملاط والرباط حول السن والعظم واللثة الصورة المقتطعة من الصفحة الأصلية توضح تموضع النسج المحيطة بالنسبة إلى التاج والجذر والعظم واللثة.","href":"page-08.html"},{"id":"i-8-1","type":"image","page":8,"pageTitle":"النسج المحيطة بالسن","section":"الصور والرسوم","text":"رسم توضيحي باللغة الإنكليزية يبين التاج والجذر واللثة واللب والعظم والأعصاب والأوعية رسم داعم يفيد في تصور علاقة اللثة بالجذر والعظم وبقية أجزاء السن.","href":"page-08.html"},{"id":"i-8-2","type":"image","page":8,"pageTitle":"النسج المحيطة بالسن","section":"الصور والرسوم","text":"مخطط عربي يوضح الميناء والعاج واللثة والعصب والرباط اللثوي والعصب ضمن مقطع سن مخطط داعم من الصورة الأصلية يساعد على فهم موقع العظم السنخي بالنسبة إلى الجذر والرباط واللثة.","href":"page-08.html"},{"id":"c-9-0-0","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"التهاب اللثة وما يتبعه من اضطرابات","text":"تركز هذه الصفحة على التهاب اللثة كأحد أكثر أمراض النسج الداعمة شيوعاً، وتعرض أهم أسبابه وأنواعه، ثم تنتقل إلى التهاب اللثة حول السن و الخراجات اللثوية الرباطية و التهاب اللثة الضخامي .","href":"page-09.html"},{"id":"c-9-0-1","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"التهاب اللثة وما يتبعه من اضطرابات","text":"المرض قد يبدأ التهاباً سطحياً في اللثة، لكنه قد يتطور إلى إصابة أعمق تمس الرباط والعظم إذا أهملت المعالجة.","href":"page-09.html"},{"id":"c-9-1-0","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"التهاب اللثة: التعريف، الأسباب، والمظاهر العامة","text":"الأسباب الرئيسية: تعد الصفيحة الجرثومية و القلح من أهم أسباب الالتهابات اللثوية.","href":"page-09.html#gingivitisIntroTitle"},{"id":"c-9-1-1","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"التهاب اللثة: التعريف، الأسباب، والمظاهر العامة","text":"من حيث التوزع: قد يكون الالتهاب موضعاً حول سن أو مجموعة أسنان، أو معمماً حول جميع الأسنان.","href":"page-09.html#gingivitisIntroTitle"},{"id":"c-9-1-2","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"التهاب اللثة: التعريف، الأسباب، والمظاهر العامة","text":"من حيث الموضع التشريحي: قد يكون حليمياً يشمل الحليمة اللثوية، أو حافياً يشمل اللثة الحفافية.","href":"page-09.html#gingivitisIntroTitle"},{"id":"c-9-1-3","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"التهاب اللثة: التعريف، الأسباب، والمظاهر العامة","text":"النزف الدوري والدائم هو الذي يرافق الحالة الالتهابية ويشتد بوجود عامل مساعد، بينما النزف العابر قد يحدث دون مرض لثوي حقيقي.","href":"page-09.html#gingivitisIntroTitle"},{"id":"c-9-2-0","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"أهم أنواع التهاب اللثة","text":"ينجم عن التحريش الموضعي، مثل حشوة بارزة أو تراكم الفضلات الطعامية. تصبح اللثة حمراء منتبجة بدرجات مختلفة، ولا يمتد الالتهاب إلى المسافة الرباطية حول السنية ولا يحدث امتصاص في النتوء السنخي.","href":"page-09.html#typesTitle"},{"id":"c-9-2-1","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"أهم أنواع التهاب اللثة","text":"يشابه البسيط لكن شدته أكبر، والعامل الجرثومي الرئيسي هو المكورات العنقودية . تنتج اللثة وتصبح حمراء مؤلمة، وقد يمتد الالتهاب إلى الغشاء المخاطي الفموي.","href":"page-09.html#typesTitle"},{"id":"c-9-2-2","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"أهم أنواع التهاب اللثة","text":"يحدث في أطوار ترافق تبدل الهرمونات أو اضطرابها، مثل المراهقة والبلوغ والحمل والطمث وسن اليأس. تميل اللثة للنزف وتتكون جيوب كاذبة، وقد يكون موضعاً أو معمماً.","href":"page-09.html#typesTitle"},{"id":"c-9-2-3","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"أهم أنواع التهاب اللثة","text":"يصيب بعض النساء في سن اليأس، وتظهر توسفات لثوية تزول بسهولة تاركة مساحات نازفة. وقد تبدأ الإصابة بشكل حويصلات تنفجر لاحقاً.","href":"page-09.html#typesTitle"},{"id":"c-9-2-4","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"أهم أنواع التهاب اللثة","text":"يسبب التنفس الفموي جفاف سطح البشرة اللثوية، فتنقص مقاومتها وتصبح أكثر عرضة للالتهاب مع تراكم الفضلات والعوامل الجرثومية.","href":"page-09.html#typesTitle"},{"id":"c-9-2-5","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"أهم أنواع التهاب اللثة","text":"إنتان حاد يسبب تقرح اللثة وتموت الحليمات اللثوية، وقد تمتد التقرحات إلى الحنك وباطن الخدين والشفاه والبلعوم الأمامي. يرافقه غشاء كاذب أصفر رمادي، نزف، رائحة نفس كريهة، ألم، حمى، وتوعك.","href":"page-09.html#typesTitle"},{"id":"c-9-2-6","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"أهم أنواع التهاب اللثة","text":"ينجم عن الإصابة بفيروس القوباء البسيط ، ويكون أكثر شدة عند الأطفال. تتشكل حويصلات بيضوية مرتفعة بقطر يقارب 2–5 ملم على باطن الشفاه والخدين واللثة واللسان، ثم تتمزق تاركة قرحات صغيرة ذات حواف حمراء مرتفعة، ويرافقها تضخم في العقد اللمفية الرقبية.","href":"page-09.html#typesTitle"},{"id":"c-9-3-0","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"صورة داعمة للالتهاب الحاد الشديد","text":"في إنتان فنسان قد يمتد الالتهاب من اللثة ليشمل قرحات السطوح الجانبية لقبة الحنك، وباطن الخدين، والشفاه، والجزء الأمامي من البلعوم. هذا يفسر الأعراض العامة الشديدة مثل الألم والحمى والتوعك.","href":"page-09.html#vincentTitle"},{"id":"c-9-3-1","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"صورة داعمة للالتهاب الحاد الشديد","text":"أما في الالتهاب الفقاعي فتبدأ الإصابة بشكل حويصلات صغيرة تتمزق سريعاً مخلفة قرحات سطحية متعددة، خاصة عند الأطفال.","href":"page-09.html#vincentTitle"},{"id":"c-9-4-0","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"التهاب اللثة حول السن والخراجات اللثوية الرباطية","text":"يمتد هذا الالتهاب من اللثة إلى العظم الواقع تحتها. من أسبابه القلح، وسوء الإطباق، والترميمات السنية السيئة، وسوء الصحة الفموية. تصبح اللثة حمراء منتبجة، ويتشكل القيح، وتتقلقل الأسنان، وقد تنتهي بسقوطها.","href":"page-09.html#periodontitisTitle"},{"id":"c-9-4-1","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"التهاب اللثة حول السن والخراجات اللثوية الرباطية","text":"يظهر في الصور الشعاعية تخرب عظمي واضح نتيجة امتصاص العظم والنتوءات السنخية، وتمتد الإصابة إلى المسافات الدقيقة للحواجز السنخية، فتتشكل الجيوب الرباطية وتزداد عمقاً باتجاه النهاية الذروية.","href":"page-09.html#periodontitisTitle"},{"id":"c-9-4-2","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"التهاب اللثة حول السن والخراجات اللثوية الرباطية","text":"تترافق أحياناً الجيوب الرباطية مع تشكل خراجات بسبب انسداد الجيب وانحصار الفضلات الطعامية وغزو الجراثيم، فيحتبس القيح ويتشكل الخراج. تبدو اللثة حمراء داكنة لامعة مائلة للزرقة، وقد يكون الألم شديداً في البداية ثم يتناقص مع تفتح الخراج وخروج القيح.","href":"page-09.html#periodontitisTitle"},{"id":"c-9-4-3","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"التهاب اللثة حول السن والخراجات اللثوية الرباطية","text":"قد تكون هذه الخراجات مفردة أو متعددة، وقد تتشكل قرب الجذور أو ضمن مفترق الجذور، ويظهر التخرب العظمي واضحاً شعاعياً، وقد تتشكل نواسير لتفريغ القيح.","href":"page-09.html#periodontitisTitle"},{"id":"c-9-5-0","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"التهاب اللثة الضخامي","text":"هو زيادة في حجم اللثة لسبب ما، وقد يأخذ أكثر من نمط مرضي أو تنسجي.","href":"page-09.html#hypertrophyTitle"},{"id":"c-9-5-1","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"التهاب اللثة الضخامي","text":"ترافق معظم أمراض اللثة وتكون مرتبطة بالحالة الالتهابية نفسها.","href":"page-09.html#hypertrophyTitle"},{"id":"c-9-5-2","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"التهاب اللثة الضخامي","text":"هي فرط نمو اللثة بسبب تنشيط الخلايا المشكلة للألياف اللثوية. من أمثلتها ما يشاهد لدى مرضى الصرع الذين يتناولون بديلاتين الصوديوم باستمرار، وقد تنمو اللثة حتى تغطي أجزاء من التاج أو تصل إلى الحدود القاطعة للأسنان الأمامية.","href":"page-09.html#hypertrophyTitle"},{"id":"c-9-5-3","type":"content","page":9,"pageTitle":"الأمراض اللثوية","section":"التهاب اللثة الضخامي","text":"هي ضخامة تنسجية تختلط لاحقاً بمظاهر التهابية.","href":"page-09.html#hypertrophyTitle"},{"id":"i-9-0","type":"image","page":9,"pageTitle":"الأمراض اللثوية","section":"الصور والرسوم","text":"صورة سريرية تبين احمراراً وانتفاخاً في اللثة الأمامية صورة مقتطعة من الصفحة الأصلية توضح مظهراً شائعاً لالتهاب اللثة مع احمرار وانتفاخ هامشي.","href":"page-09.html"},{"id":"i-9-1","type":"image","page":9,"pageTitle":"الأمراض اللثوية","section":"الصور والرسوم","text":"رسم يقارن بين الحالة الطبيعية وحالة الالتهاب في الفم والبلعوم رسم مقتطع من الصفحة الأصلية يفيد في تصور امتداد الالتهاب إلى النسج الفموية والبلعومية عند الحالات الشديدة.","href":"page-09.html"},{"id":"i-9-2","type":"image","page":9,"pageTitle":"الأمراض اللثوية","section":"الصور والرسوم","text":"صورة سريرية لخراج لثوي فوق الأسنان الأمامية العلوية صورة مقتطعة من الصفحة الأصلية مثال سريري على تشكل خراج لثوي رباطي مع انتفاخ موضعي واضح.","href":"page-09.html"},{"id":"c-10-0-0","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"حركة الأسنان، الانحسار اللثوي، صرير الأسنان، والإطباق الرضي","text":"تعرض هذه الصفحة عدداً من الاضطرابات السريرية المهمة التي تصيب النسج الداعمة والأسنان، بدءاً من الحركة المرضية للأسنان و الانحسار اللثوي ، مروراً بـ صرير الأسنان ، ووصولاً إلى الإطباق الرضي و التواج .","href":"page-10.html"},{"id":"c-10-0-1","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"حركة الأسنان، الانحسار اللثوي، صرير الأسنان، والإطباق الرضي","text":"تربط الصفحة بين الأعراض السريرية والسبب الوظيفي أو الميكانيكي المؤدي لاضطراب النسج حول الأسنان.","href":"page-10.html"},{"id":"c-10-1-0","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"حركة الأسنان","text":"للأسنان حركة طبيعية دهليزية لسانية وبشكل أقل أنسية وحشية، وهذه الحركة تكاد لا تُرى في الأسنان الخلفية.","href":"page-10.html#toothMobilityTitle"},{"id":"c-10-1-1","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"حركة الأسنان","text":"أما الحركة المرضية للأسنان فتنتج عن فقدان جزئي أو تام للأنسجة الداعمة، كما في مرض الرعّال أو في حالات اتساع الرباط المترافق مع تناقص الدعم العظمي للأسنان.","href":"page-10.html#toothMobilityTitle"},{"id":"c-10-1-2","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"حركة الأسنان","text":"درجة أولى: تتحرك السن بالاتجاه الدهليزي اللساني.","href":"page-10.html#toothMobilityTitle"},{"id":"c-10-1-3","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"حركة الأسنان","text":"درجة ثانية: تتحرك السن بالاتجاه الأنسي الوحشي بالإضافة إلى الاتجاه الدهليزي اللساني.","href":"page-10.html#toothMobilityTitle"},{"id":"c-10-1-4","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"حركة الأسنان","text":"درجة ثالثة: تتحرك السن حركة شاقولية بالإضافة إلى الدرجتين السابقتين.","href":"page-10.html#toothMobilityTitle"},{"id":"c-10-2-0","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الانحسار اللثوي","text":"هو تراجع النسج الداعمة بما فيها اللثة عن السن، وينتج عن:","href":"page-10.html#recessionTitle"},{"id":"c-10-2-1","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الانحسار اللثوي","text":"الصفيحة الجرثومية وما تطرحه من مواد تحلّ الارتباط بين السن والنسج المحيطة به.","href":"page-10.html#recessionTitle"},{"id":"c-10-2-3","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الانحسار اللثوي","text":"ارتكاز الألجمة المنخفض كألجمة الشفة أو الألجمة الجانبية، مما يؤدي إلى انحسار اللثة عن السن المجاور للحاج.","href":"page-10.html#recessionTitle"},{"id":"c-10-2-4","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الانحسار اللثوي","text":"تتدخل عوامل أخرى في ظهور الانحسار اللثوي بشكل واضح، منها:","href":"page-10.html#recessionTitle"},{"id":"c-10-2-5","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الانحسار اللثوي","text":"سماكة النسج العظمي المغطي: مثل الناب السفلي حيث تكون الصفيحة الدهليزية رقيقة جداً، وكذلك الصفيحة الحنكية للرحى الأولى والثانية العلوية.","href":"page-10.html#recessionTitle"},{"id":"c-10-2-6","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الانحسار اللثوي","text":"انحسارات تحدث في سياق التقريش الخاطئ.","href":"page-10.html#recessionTitle"},{"id":"c-10-2-7","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الانحسار اللثوي","text":"الأجهزة الصناعية السنية السيئة.","href":"page-10.html#recessionTitle"},{"id":"c-10-2-8","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الانحسار اللثوي","text":"والسبب في بعض الأسنان هو اقترابها من أماكن انصباب اللعاب في الفم.","href":"page-10.html#recessionTitle"},{"id":"c-10-2-9","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الانحسار اللثوي","text":"فلجام الشفة السفلية يتدخل في الانحسار اللثوي كثير الحدوث على السطوح الدهليزية للثنايا السفلية.","href":"page-10.html#recessionTitle"},{"id":"c-10-3-0","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"صرير الأسنان","text":"صرير الأسنان هو داء التشنج العضلي غير الطبيعي لعضلات المضغ.","href":"page-10.html#bruxismTitle"},{"id":"c-10-3-1","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"صرير الأسنان","text":"يجب تمييز الصرير المرضي عن الصرير الطارئ الذي قد يظهر عرضاً بعد بعض الأمراض الناتجة عن التشنج العضلي العابر، فتتشنج عضلات المضغ مؤقتاً مما يؤدي إلى احتكاك الأسنان مع بعضها.","href":"page-10.html#bruxismTitle"},{"id":"c-10-3-2","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"صرير الأسنان","text":"الصرير المرضي هو وجود هذه الظاهرة بشكل مستمر ومن دون الدواعي السابقة، وبالشكل الذي يهدد سلامة النسج السنية وما حول السنية.","href":"page-10.html#bruxismTitle"},{"id":"c-10-3-3","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"صرير الأسنان","text":"انسحال غير طبيعي للدرجة قد يفقد معها السن قسماً كبيراً من التاج.","href":"page-10.html#bruxismTitle"},{"id":"c-10-3-4","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"صرير الأسنان","text":"قد يحدث كسر في الميناء أو التيجان في مناطق الضغط.","href":"page-10.html#bruxismTitle"},{"id":"c-10-3-5","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"صرير الأسنان","text":"آلام في عضلات المضغ، ثم قد تنتشر إلى عضلات العنق والرأس والكتف.","href":"page-10.html#bruxismTitle"},{"id":"c-10-3-6","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"صرير الأسنان","text":"قد يترافق بألم وأصوات في المفصل الفكي الصدغي وصداع صباحي.","href":"page-10.html#bruxismTitle"},{"id":"c-10-3-7","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"صرير الأسنان","text":"قد نحتاج إلى المعالجة النفسية وإعطاء المرخيات العضلية أو المنومات، وتكون المعالجة الفيزيائية لاضطرابات المفصل الفكي الصدغي كما يلي:","href":"page-10.html#bruxismTitle"},{"id":"c-10-3-8","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"صرير الأسنان","text":"التمرين الأول: وضع اللسان في أقصى وضع خلفي قرب اللهاة في قبة الحنك ثم فتح الفم قسرياً بما يؤدي إلى تعب عضلات المضغ والغاية من هذا حدوث توازن عضلي في الطرفين وجعل محصلة عمل العضلات في الجانبين تساوي الصفر.","href":"page-10.html#bruxismTitle"},{"id":"c-10-3-9","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"صرير الأسنان","text":"التمرين الثاني: فتح الفم وإغلاقه على الخط المتوسط.","href":"page-10.html#bruxismTitle"},{"id":"c-10-3-10","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"صرير الأسنان","text":"التمرين الثالث: فتح الفم قسرياً واليد موضوعة على الفك السفلي.","href":"page-10.html#bruxismTitle"},{"id":"c-10-3-11","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"صرير الأسنان","text":"والمعالجة النهائية للصرير هي تعديل الإطباق.","href":"page-10.html#bruxismTitle"},{"id":"c-10-4-0","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"هو قوى إطباقية غير طبيعية تقع على الأسنان محدثة أضراراً في النسج الداعمة للسن.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-1","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"سوء توضع الأسنان الخلفي أو وجود أسنان زائدة أو الناتج عن القلع المبكر للأسنان اللبنية.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-2","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"قلع الأسنان الدائمة وعدم التعويض عنها وما يرافقه من ميلان الأسنان المجاورة لمنطقة القلع باتجاه الفراغ، وكذلك تطاول السن المقابلة للفراغ باتجاه هذا الفراغ.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-3","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"العادات الفموية السيئة كعض الشفة واللسان ومسك بعض الأدوات بالفم.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-5","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"الترميمات والأجهزة الصناعية السيئة التي لا تراعي العلاقات الإطباقية ونقاط التماس.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-6","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"ألم متمثل في المفصل الفكي الصدغي وآلام عضلية للعضلات الماضغة.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-8","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"حساسية الأسنان إذا أدى الإطباق الرضي إلى سحل ميناء الأسنان وانكشاف العاج.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-10","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"تشكل الجيوب اللثوية إذا ما ترافق الإطباق الرضي مع صفيحة جرثومية.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-11","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"نقص الدعم العظمي للأسنان بسبب امتصاص العظم وتراجع كل من اللثة والعظم وبالتالي تقلقل الأسنان وحركتها.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-13","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"التعويض عن الأسنان المفقودة مباشرة.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-14","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"معالجة النخور السنية مباشرة قبل تطورها ومعالجة الأسنان التي تكون مصدر آلام لمنع المضغ وحيد الجانب.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-15","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"تجنب الترميمات والتعويضات الصناعية السيئة والانتباه عند صنعها إلى نقاط التماس والعلاقات الإطباقية الصحيحة.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-16","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"استبعاد العادات الفموية الضارة.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-17","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"تصحيح الإطباق بالسحل لخلق تحريض ملائم للأربطة السنخية حتى تحافظ على سلامتها من التشوهات.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-18","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"تصحيح الإطباق بالتعويضات الصناعية.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-19","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"تصحيح الإطباق بالتقويم وذلك بإعادة الأسنان الشاذة إلى وضعها الطبيعي تقويمياً.","href":"page-10.html#traumaTitle"},{"id":"c-10-4-20","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"الإطباق الرضي","text":"إزالة أسباب الصرير ومنع فرط نشاط العضلات الماضغة.","href":"page-10.html#traumaTitle"},{"id":"c-10-5-0","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"التواج","text":"هو التهاب النسج المحيطة بسن في طور البزوغ، وغالباً ما تكون الرحى الثالثة السفلية هي المصابة، ويغلب أن تنمو الحافة اللثوية وتغطي جزءاً من التاج.","href":"page-10.html#pericoronitisTitle"},{"id":"c-10-5-1","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"التواج","text":"يمكن أن يكون الالتهاب حاداً أو تحت الحاد أو مزمناً أو ناكِساً .","href":"page-10.html#pericoronitisTitle"},{"id":"c-10-5-2","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"التواج","text":"تترافق الحالة بألم شديد وقد ينتقل الالتهاب نحو الخد وأحياناً اللوزات والبلعوم وقاع الفم، وقد تترافق بنسج عضلي يمنع المريض من فتح فمه، وهذا ما يدعى الضزز .","href":"page-10.html#pericoronitisTitle"},{"id":"c-10-5-3","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"التواج","text":"تعتمد المعالجة على قطع القلنسوة اللثوية وغسل المنطقة جيداً بشكل متكرر، كما تفيد المضامض الفموية في هذه الحالة.","href":"page-10.html#pericoronitisTitle"},{"id":"c-10-5-4","type":"content","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"التواج","text":"تنتهي هذه الصفحة عند بداية عنوان سابعاً: كسور الفكين ، وسيُبنى هذا العنوان في الصفحة التالية ضمن تسلسل المشروع.","href":"page-10.html#pericoronitisTitle"},{"id":"c-11-0-0","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم بأشكاله المختلفة","text":"تتناول هذه الصفحة الأنماط السريرية المهمة من التهاب الفم ، وتشمل: التهاب الفم القلاعي ، و التهاب الفم واللثة التبغي ، و التهاب الفم الناتج عن التعويضات الصناعية ، إضافة إلى التهاب الفم الناتج عن التحسس للمعادن بأنواعه المختلفة.","href":"page-11.html"},{"id":"c-11-0-1","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم بأشكاله المختلفة","text":"تربط الصفحة بين المسببات الموضعية والدوائية والمهنية وبين صور الالتهاب المختلفة في الغشاء المخاطي الفموي.","href":"page-11.html"},{"id":"c-11-1-0","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم القلاعي","text":"يمثل بالتهاب اللثة الناجمة عن غياب الصحة الفموية السنية بسبب تجمع الصفيحة اللثوية السنية وتحولها إلى قلح، وقد تزداد شدة الالتهاب أو احتمال حدوثه عندما لا يتعلق المضغ الجيد أو تنحشر فضلات الطعام بين نقاط التماس أو تتوضع الأسنان بشكل خاطئ.","href":"page-11.html#aphthousTitle"},{"id":"c-11-1-1","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم القلاعي","text":"يتظاهر هذا الالتهاب بحليمات لثوية حمراء أو وذمية محتقنة أو حليمات أتوية تنزف عند أقل تماس. يكثر في مناطق القلح، وخاصة اللسانية للقواطع السفلية بسبب قربها من فوهة الغدة تحت اللسان، والدهليزية للأرحاء العلوية بسبب قربها من فوهة قناة الغدة النكفية.","href":"page-11.html#aphthousTitle"},{"id":"c-11-1-2","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم القلاعي","text":"تعتمد المعالجة على إزالة القلح والعناية بالصحة الفموية ومعالجة الأسنان النخرة وإعادة نقاط التماس وإصلاح وضع الأسنان الشاذة تقويمياً عند الحاجة.","href":"page-11.html#aphthousTitle"},{"id":"c-11-2-0","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم واللثة التبغي","text":"يبين تحليل التبغ وجود عدة مواد محرّضة للالتهاب، أهمها: حمض سيان هيدريك ، و أكسيد الأزوت ، و الفينول ، و القطران .","href":"page-11.html#smokerTitle"},{"id":"c-11-2-1","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم واللثة التبغي","text":"هذه المواد ندفانات خلوية تحرض ردود فعل نسجية التهابية، كما أن للتبغ تأثيراً سُمّياً في الغشاء الفموي والغشاء المخاطي لجهاز التنفس حيث يؤدي إلى إلغاء النشاط الهدبي.","href":"page-11.html#smokerTitle"},{"id":"c-11-2-2","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم واللثة التبغي","text":"النيكوتين ينقص إفراز اللعاب ويحرض زيادة الدوران الدموي ويؤدي إلى ضمور الغشاء المخاطي. كما أن التسمم بالتبغ بسبب الإفراط فيه غالباً ما يرافقه غياب العناية الفموية مما يزيد سوء الحالة.","href":"page-11.html#smokerTitle"},{"id":"c-11-2-3","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم واللثة التبغي","text":"تكون المعالجة في هذه الحالة صعبة لأنها تعتمد على المعالجة السببية، أي الإقلاع عن التدخين ، وهي غالباً ما تكون شبه مستحيلة عند بعض المرضى.","href":"page-11.html#smokerTitle"},{"id":"c-11-2-4","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم واللثة التبغي","text":"الآثار التخريشية والسُمّية للتبغ لا تسبب الالتهاب فقط، بل تضعف أيضاً مقاومة النسج المخاطية وتعيق تنظيفها الطبيعي.","href":"page-11.html#smokerTitle"},{"id":"c-11-3-0","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التعويضات الصناعية","text":"ينتج عن وجود أعراض في الفم وترتفع نسبة الإصابة به في الأجهزة فاشلة الصنع، ويتجلى ذلك بوجود تقرحات رضية بعد استعمال جهاز ذي حواف غير منتظمة وتكون مؤلمة مغطاة بنسج رمادي متموت ومحاطة بنسيج التهابي.","href":"page-11.html#prosthesisTitle"},{"id":"c-11-3-1","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التعويضات الصناعية","text":"الضغط غير الفيزيولوجي المباشر بواسطة التعويضات على الغشاء المخاطي.","href":"page-11.html#prosthesisTitle"},{"id":"c-11-3-2","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التعويضات الصناعية","text":"هشاشة الأوعية الشعرية، وتزداد عند سن بعد العقد الثالث من العمر.","href":"page-11.html#prosthesisTitle"},{"id":"c-11-3-3","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التعويضات الصناعية","text":"الخرش الفموي والضغط على سطح الغشاء المخاطي الملامس للتعويضات حيث يكون مكشوفاً ومساميّاً.","href":"page-11.html#prosthesisTitle"},{"id":"c-11-3-4","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التعويضات الصناعية","text":"استطالة حواف الجهاز أو وجود نتوءات عظمية بارزة على الحافة السنخية أو الخشونة الموجودة داخل الجهاز.","href":"page-11.html#prosthesisTitle"},{"id":"c-11-3-5","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التعويضات الصناعية","text":"قد يكون سوء الإطباق سبباً في ذلك.","href":"page-11.html#prosthesisTitle"},{"id":"c-11-3-6","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التعويضات الصناعية","text":"تدوم هذه التقرحات من 7–10 أيام وتشفى دون ندبة، وقد تتحول التقرحات في منطقة حواف الجهاز إلى طيات مخاطية التهابية وهي فرط في نمو النسج في منطقة الدهليز. وإذا استمر التخريش قد تتحول هذه الطيات إلى أورام خبيثة.","href":"page-11.html#prosthesisTitle"},{"id":"c-11-3-7","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التعويضات الصناعية","text":"استعمال التعويضات الثابتة ما أمكن والتعويضات الهيكلية ذات الدعم السني.","href":"page-11.html#prosthesisTitle"},{"id":"c-11-3-8","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التعويضات الصناعية","text":"أن تكون التعويضات اللدنة عند الضرورة متقنة الصنع.","href":"page-11.html#prosthesisTitle"},{"id":"c-11-3-9","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التعويضات الصناعية","text":"نزع التعويضات باستمرار وتطهيرها بالمؤكسدات ومعالجة التقرحات.","href":"page-11.html#prosthesisTitle"},{"id":"c-11-3-10","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التعويضات الصناعية","text":"الطيات المخاطية تزال بالجراحة.","href":"page-11.html#prosthesisTitle"},{"id":"c-11-4-0","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التحسس للمعادن","text":"تشاهد التهابات الفم المعدنية في حالات التعرض المزمن للمعادن وامتصاصها حيث تحدث تقرحات في الغشاء المخاطي الفموي، ونميز عدة أنواع منها.","href":"page-11.html#metalTitle"},{"id":"c-11-4-1","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التحسس للمعادن","text":"يمكن للزئبق أن يُمتص من خلال الجلد أو الجهاز التنفسي أو الجهاز الهضمي. تؤدي الإصابة إلى التهاب لثة تقرحي مع انتباج في الشفاه واللسان وغزارة في اللعاب، ويمكن أن تفقد الأسنان إذا شمل التهرب العظم. تتدرج التصبغات الرمادية مع تقدم الالتهاب.","href":"page-11.html#metalTitle"},{"id":"c-11-4-2","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التحسس للمعادن","text":"المعالجة تتضمن التوقف عن التعرض للزئبق مع تناول الأدوية التي تساعد على طرحه.","href":"page-11.html#metalTitle"},{"id":"c-11-4-3","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التحسس للمعادن","text":"لا يزال الفوسفور يدخل في بعض المواد الصناعية المستخدمة حتى الآن، ويتميز هذا الالتهاب بالتقرح مع ضياع سريع لأسنان المصاب بسبب تخرب العظم وإصابته بالتهاب العظم والنقي الثانوي.","href":"page-11.html#metalTitle"},{"id":"c-11-4-4","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التحسس للمعادن","text":"تعتمد الوقاية على منع حدوث الالتهاب، وتشمل معالجة المصاب استعمال المضادات الحيوية والاستئصال الجراحي للتشكلّات النسجية عند الحاجة.","href":"page-11.html#metalTitle"},{"id":"c-11-4-5","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التحسس للمعادن","text":"الرصاص: إيقاف التعرض للمادة الرصاصية فتختفي الرواسب والخط اللثوي تدريجياً.","href":"page-11.html#metalTitle"},{"id":"c-11-4-6","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التحسس للمعادن","text":"الزرنيخ: عزل العامل المسبب أولاً، وفي الحالات الشديدة تعطى الأدوية المساعدة على التخلص منه.","href":"page-11.html#metalTitle"},{"id":"c-11-4-7","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التحسس للمعادن","text":"البرموت: يوصى بإيقاف الدواء الحاوي على البرموت أو إبعاد المريض عن بيئة التعرض، ويختفي الخط الأسود خلال شهرين إلى ثلاثة مع وسائل الصحة الفموية.","href":"page-11.html#metalTitle"},{"id":"c-11-4-8","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التحسس للمعادن","text":"الزئبق: التوقف عن التعرض مع الأدوية الطارحة له.","href":"page-11.html#metalTitle"},{"id":"c-11-4-9","type":"content","page":11,"pageTitle":"التهاب الفم","section":"التهاب الفم الناتج عن التحسس للمعادن","text":"الفوسفور: الوقاية المهنية ثم المعالجة بالمضادات الحيوية والجراحة عند الضرورة.","href":"page-11.html#metalTitle"},{"id":"c-12-0-0","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"القلاع، الضخامة الدوائية، السلاق، والنكاف","text":"تجمع هذه الصفحة أربع موضوعات مترابطة سريرياً: القلاع كآفة تقرحية مؤلمة، و ضخامة اللثة المرتبطة بالديلانتين ، و السلاق الناتج عن فطر المبيضات، و النكاف بوصفه التهاباً فيروسياً يصيب الغدد اللعابية، ولا سيما الغدة النكفية.","href":"page-12.html"},{"id":"c-12-0-1","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"القلاع، الضخامة الدوائية، السلاق، والنكاف","text":"يتميّز كل موضوع بسبب مختلف: مناعي أو دوائي أو فطري أو فيروسي، ولذلك تختلف الوقاية والمعالجة.","href":"page-12.html"},{"id":"c-12-1-0","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"القلاع","text":"القلاع من الأمراض التي تصيب الفم، ويتصف بحدوث تقرح بسيط قطره نحو 1–5 ملم ، وقد يكون وحيداً أو متعدداً ومؤلماً، وله مركز مصفر تحيط به هالة حمراء. يبقى الاندفاع المؤلم بضعة أيام ثم يشفى عفوياً.","href":"page-12.html#aphthaeTitle"},{"id":"c-12-1-1","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"القلاع","text":"أما التهاب الفم القلاعي فيتظاهر بتعدد الاندفاعات القلاعية، مع الألم وزيادة اللعاب وارتفاع الحرارة أحياناً.","href":"page-12.html#aphthaeTitle"},{"id":"c-12-1-2","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"القلاع","text":"تكون الآفة في البداية حطاطية، وقد تنتشر أحياناً على شكل حويصلات صغيرة سريعة الزوال. وبعد نحو 24 ساعة قد تتحول إلى تقرحات سطحية تكبر بسرعة حتى يبلغ قطرها نحو 0.5 سم ، وتأخذ شكلاً بيضوياً قليل العمق ومركزاً أصفر محاطاً بهالة أو شريط أحمر.","href":"page-12.html#aphthaeTitle"},{"id":"c-12-1-3","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"القلاع","text":"تكون الآفات مؤلمة عند اللمس، وتتوزع في مخاطية الشفة والدهليز والخدود واللسان وقاع الفم.","href":"page-12.html#aphthaeTitle"},{"id":"c-12-2-0","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"التهاب اللثة الضخامي الناجم عن استعمال الديلانتين","text":"الديلانتين دواء يعطى للمصابين بمرض الصرع، وقد ينجم عن استعماله تضخم في اللثة بدرجات تختلف تبعاً لمدة تناول الدواء وشدة الاستجابة، وقد تصبح الضخامة كبيرة إلى درجة تطوق الأسنان وتغطيها في الحالات المزمنة.","href":"page-12.html#dilantinTitle"},{"id":"c-12-2-1","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"التهاب اللثة الضخامي الناجم عن استعمال الديلانتين","text":"لا تحدث هذه الضخامة عادةً في المناطق الرداء، بينما يزيد سوء الإطباق وضعف الصحة الفموية والمخرشات السنية الموضعية من شدتها.","href":"page-12.html#dilantinTitle"},{"id":"c-12-2-2","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"التهاب اللثة الضخامي الناجم عن استعمال الديلانتين","text":"قوام اللثة قاسٍ وغير مؤلم.","href":"page-12.html#dilantinTitle"},{"id":"c-12-2-3","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"التهاب اللثة الضخامي الناجم عن استعمال الديلانتين","text":"تميل الضخامة إلى شمول الأسنان الأمامية بصورة واسعة.","href":"page-12.html#dilantinTitle"},{"id":"c-12-2-4","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"التهاب اللثة الضخامي الناجم عن استعمال الديلانتين","text":"قد تأخذ اللثة لوناً قرنفلياً.","href":"page-12.html#dilantinTitle"},{"id":"c-12-2-5","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"التهاب اللثة الضخامي الناجم عن استعمال الديلانتين","text":"تميل إلى النكس بعد الاستئصال الجراحي.","href":"page-12.html#dilantinTitle"},{"id":"c-12-3-0","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"السلاق","text":"السلاق إنتان فطري تشبه فطوره الخمائر، وأهمها المبيضات البيض (Candida albicans) . تسكن هذه الفطور في الفم بشكل طبيعي من دون أن تسبب مرضاً، كما توجد في الأنبوب الهضمي. وعند ظهور المرض يجب البحث عن سبب أو عوامل مهيئة موضعية أو عامة.","href":"page-12.html#thrushTitle"},{"id":"c-12-3-1","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"السلاق","text":"الفم هو المنطقة الأكثر إصابة، وتتعرض له الخدود واللثة وقاع الفم، وقد يمتد إلى زاوية الفم. يشاهد عند النساء الحوامل، وعند من يتناولون كميات كبيرة من الكورتيزون، وقد يتجاوز حدود الفم نادراً فيصيب البلعوم والحنجرة والجلد والأنبوب الهضمي والمسالك البولية.","href":"page-12.html#thrushTitle"},{"id":"c-12-3-2","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"السلاق","text":"الأطفال الرضع الضعفاء وكبار السن.","href":"page-12.html#thrushTitle"},{"id":"c-12-3-3","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"السلاق","text":"العدوى عبر زجاجات الحليب عند الأطفال.","href":"page-12.html#thrushTitle"},{"id":"c-12-3-4","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"السلاق","text":"الأمراض المزمنة مثل السكري والعوز الفيتاميني، ولا سيما مجموعة فيتامين (B) والريبوفلافين وفيتامين (B12).","href":"page-12.html#thrushTitle"},{"id":"c-12-3-5","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"السلاق","text":"داء أديسون وسرطان الدم وسوء التغذية.","href":"page-12.html#thrushTitle"},{"id":"c-12-3-6","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"السلاق","text":"الاستعمال المطول لبعض المضادات الحيوية.","href":"page-12.html#thrushTitle"},{"id":"c-12-3-7","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"السلاق","text":"إن تناول بعض المضادات الحيوية لمدد طويلة قد يخل بالتوازن الجرثومي والفطري في الفم، فيهيئ لظهور السلاق.","href":"page-12.html#thrushTitle"},{"id":"c-12-4-0","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"النكاف","text":"يسمى النكاف التهاب الغدة النكفية الوبائي ، وهو مرض جهازي أكثر منه موضعياً. يصيب الغدد اللعابية، وأكثر ما تتأثر به الغدة النكفية، وقد يصيب أيضاً الخصيتين والجملة العصبية.","href":"page-12.html#mumpsTitle"},{"id":"c-12-4-1","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"النكاف","text":"قد يكون الالتهاب أحادي الجانب أو ثنائياً، وتتراوح فترة الحضانة بين 2–3 أسابيع . العامل الممرض فيروس (RNA) من الفصيلة المخاطية، وينتشر عن طريق التماس والرذاذ اللعابي.","href":"page-12.html#mumpsTitle"},{"id":"c-12-4-2","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"النكاف","text":"انفعال نفسي، نقص الشهية، صداع، وحمى.","href":"page-12.html#mumpsTitle"},{"id":"c-12-4-3","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"النكاف","text":"ألم في الخدين، ولا سيما عند المضغ.","href":"page-12.html#mumpsTitle"},{"id":"c-12-4-4","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"النكاف","text":"انتفاخ غدي مميز أمام وأسفل وخلف الأذن، مع وجود طفح خاص حول فوهة قناة ستنسن.","href":"page-12.html#mumpsTitle"},{"id":"c-12-4-7","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"النكاف","text":"يبدأ الانتفاخ بالزوال بعد 7–10 أيام.","href":"page-12.html#mumpsTitle"},{"id":"c-12-4-8","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"النكاف","text":"التهاب الخصية أو المبيض، وقد يؤدي إلى العقم.","href":"page-12.html#mumpsTitle"},{"id":"c-12-4-9","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"النكاف","text":"التهاب البنكرياس، وقد يترافق بألم بطني وإقياء.","href":"page-12.html#mumpsTitle"},{"id":"c-12-4-10","type":"content","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"النكاف","text":"التهاب السحايا أو الدماغ والصمم.","href":"page-12.html#mumpsTitle"},{"id":"i-12-0","type":"image","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"الصور والرسوم","text":"قرحتان قلاعيتان صغيرتان على مخاطية الشفة السفلية الصورة الموجودة في الصفحة الأصلية تظهر قرحات صغيرة ذات مركز فاتح وهالة حمامية محيطة.","href":"page-12.html"},{"id":"c-13-0-0","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"آفات تمهيدية للسرطان وآفات سرطانية داخل الفم","text":"تتناول هذه الصفحة أربع محاور رئيسية: الطلاوة (Leukoplakia) بوصفها آفة ما قبل سرطانية مهمة، ثم سرطان مخاطية دهليز الفم ، و سرطان اللثة ، و سرطان الشفة ، وأخيراً سرطان اللسان . تركّز الصفحة على المظهر السريري، أماكن التوضع، والعوامل المهيئة والأسباب الرئيسية.","href":"page-13.html"},{"id":"c-13-0-1","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"آفات تمهيدية للسرطان وآفات سرطانية داخل الفم","text":"كل آفة فموية بيضاء أو متقرحة مزمنة أو متبدلة الحجم تحتاج إلى تقييم مهني مبكر.","href":"page-13.html"},{"id":"c-13-1-0","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"الطلاوة","text":"الطلاوة إحدى الآفات التي تتوضع على سطح الأغشية المخاطية للفم، وقد تشاهد أيضاً في بعض المخاطيات الأخرى. تصيب الرجال أكثر من النساء، ولا سيما المتقدمين بالعمر، ويكون العمر المتوسط للمصابين نحو 60 سنة ، وغالبهم فوق الأربعين.","href":"page-13.html#leukoplakiaTitle"},{"id":"c-13-1-1","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"الطلاوة","text":"أكثر أماكن توضعها: الغشاء المخاطي الدهليزي، والحافة السنية للفك السفلي، واللسان، وقبة الحنك، وقاع الفم.","href":"page-13.html#leukoplakiaTitle"},{"id":"c-13-1-2","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"الطلاوة","text":"قد تختلف الطلاوة من بقع صغيرة إلى سطوح واسعة تغطي أجزاء كبيرة من الغشاء المخاطي. ويكون لونها أبيض رمادياً أو أبيض مصفراً، وغالباً ما يكون سطحها متجعّداً أو خشناً بشكل واضح.","href":"page-13.html#leukoplakiaTitle"},{"id":"c-13-2-0","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"سرطان مخاطية دهليز الفم","text":"يشكل هذا السرطان نحو 9% من سرطانات داخل الفم، وهو أكثر شيوعاً عند المتقدمين بالعمر، ويشاهد عند الرجال أكثر بكثير من النساء.","href":"page-13.html#vestibuleTitle"},{"id":"c-13-2-1","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"سرطان مخاطية دهليز الفم","text":"من أهم أسبابه: مضغ التبغ وبعض المواد الشبيهة به، ويكثر في الجهة التي اعتاد الشخص أن يمضغ عليها. ويظهر في أكثر الحالات على طول الخط المجاور لمستوى الإطباق أو أخفض قليلاً.","href":"page-13.html#vestibuleTitle"},{"id":"c-13-2-2","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"سرطان مخاطية دهليز الفم","text":"قد تكون الآفة متقرحة ومؤلمة ، وقد تنمو في عمق النسج أو تكون ثؤلولية نامية نحو الخارج.","href":"page-13.html#vestibuleTitle"},{"id":"c-13-3-0","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"سرطان اللثة وسرطان الشفة","text":"يشكل نحو 10–11% من سرطانات داخل الفم، وقد يشبه التهابات اللثة السنية المنشأ مما يؤدي إلى تأخر اكتشافه أو سوء تشخيصه. متوسط العمر المذكور لسرطان اللثة هو 61 سنة .","href":"page-13.html#gingivaLipTitle"},{"id":"c-13-3-1","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"سرطان اللثة وسرطان الشفة","text":"من أهم العوامل المهيئة: التخريش المزمن، والالتهاب الناتج عن القلح، وبعض العوامل الموضعية طويلة الأمد. ويتوضع أكثر ما يتوضع في لثة الفك السفلي.","href":"page-13.html#gingivaLipTitle"},{"id":"c-13-3-2","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"سرطان اللثة وسرطان الشفة","text":"قد يكون السرطان مؤلماً أو غير مؤلم، ويزداد خطر امتداده بسبب قرب اللثة من العظم.","href":"page-13.html#gingivaLipTitle"},{"id":"c-13-3-3","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"سرطان اللثة وسرطان الشفة","text":"يشاهد أكثر عند الرجال بنسبة تقارب 86–98% من الحالات، ويصيب الشفة السفلى في معظم الإصابات بنسبة عالية، بينما تكون إصابة الشفة العليا أقل بكثير.","href":"page-13.html#gingivaLipTitle"},{"id":"c-13-3-4","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"سرطان اللثة وسرطان الشفة","text":"يعد التدخين من أهم أسبابه، ويظهر سريرياً في المنطقة الحمراء الانتقالية للشفة، غالباً قرب الخط المتوسط، وقد يأخذ شكل فوهة بركان أو كتلة ورقية بارزة.","href":"page-13.html#gingivaLipTitle"},{"id":"c-13-4-0","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"سرطان اللسان","text":"يشكل سرطان اللسان نسبة كبيرة من مجموع السرطانات داخل الفموية، ويصيب الرجال أكثر من النساء. لا توجد له أسباب نوعية قاطعة، لكن الالتهاب المزمن، والتخريش المستمر، والتدخين، والكحول، وسوء صحة الفم كلها عوامل ترفع احتمال حدوثه.","href":"page-13.html#tongueTitle"},{"id":"c-13-4-1","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"سرطان اللسان","text":"غالباً ما يتوضع على السطوح الجانبية أو السطح السفلي للسان ، ونادراً ما يظهر على ظهر اللسان. وقد لا يترافق بالألم إلا إذا حدث التهاب ثانوي.","href":"page-13.html#tongueTitle"},{"id":"c-13-4-2","type":"content","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"سرطان اللسان","text":"تعالج الحالات بصعوبة نسبية، ويكون العلاج بالجراحة أو بالأشعة وفق التقييم الاختصاصي.","href":"page-13.html#tongueTitle"},{"id":"i-13-0","type":"image","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"الصور والرسوم","text":"صورة سريرية لطلاوة على اللسان صورة من المصدر توضح مظهراً أبيض متبقعاً على اللسان ضمن قسم الطلاوة.","href":"page-13.html"},{"id":"i-13-1","type":"image","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"الصور والرسوم","text":"صورة أخرى لطلاوة على ظهر اللسان صورة داعمة من المصدر تفيد في المقارنة البصرية لمظاهر الطلاوة.","href":"page-13.html"},{"id":"i-13-2","type":"image","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"الصور والرسوم","text":"صورة سريرية لآفة سرطانية في دهليز الفم أو قرب الشفة صورة من المصدر تم إيرادها ضمن جزء سرطان مخاطية دهليز الفم في المادة الأصلية.","href":"page-13.html"},{"id":"i-13-3","type":"image","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"الصور والرسوم","text":"صورة سريرية لسرطان الشفة الصورة السريرية الواردة في المصدر تعكس مظهراً متقدماً لإصابة خبيثة في الشفة.","href":"page-13.html"},{"id":"i-13-4","type":"image","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"الصور والرسوم","text":"صورة فموية سريرية واردة في المصدر ضمن هذا القسم الصورة الملحقة في المصدر أُدرجت كما وردت في الصفحة الأصلية دون إعادة تصميم.","href":"page-13.html"},{"id":"c-14-0-0","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"القلح (Calculus) والتلونات السنية","text":"تعرض هذه الصفحة تعريف القلح وتركيبه وتوضعه السريرية، ثم تميّز بين نوعيه: القلح فوق اللثوي/اللعابي و القلح تحت اللثوي/المصلي . كما تستعرض التلونات السنية وأهم أنماطها، خاصة التلونات المرتبطة بالتبغ والمعادن.","href":"page-14.html"},{"id":"c-14-0-1","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"القلح (Calculus) والتلونات السنية","text":"القلح يبدأ من الصفحة السنية، وقد يتشكل أحياناً حتى دون وجود صفحة سنية واضحة.","href":"page-14.html"},{"id":"c-14-1-0","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"القلح","text":"القلح هو كتل صلبة متكلسة تلتصق على سطوح الأسنان والتعويضات الصناعية. يتركب من أملاح معدنية بنسبة تقارب 70–90% ، وتشكل فوسفات الكالسيوم النسبة الغالبة من هذه الأملاح، مع وجود كربونات الكالسيوم وفوسفات المغنزيوم.","href":"page-14.html#calculusTitle"},{"id":"c-14-1-1","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"القلح","text":"أما المحتوى العضوي فيتألف من مزيج من بروتينات عديدة السكريات، مع خلايا متوسفة، وكريات بيض، وعضويات دقيقة.","href":"page-14.html#calculusTitle"},{"id":"c-14-1-2","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"القلح","text":"يتوضع القلح على معظم الأسنان تقريباً، لكنه يكثر في مناطق الانصباب اللعابي، وبخاصة:","href":"page-14.html#calculusTitle"},{"id":"c-14-1-3","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"القلح","text":"السطوح اللسانية للقواطع السفلية.","href":"page-14.html#calculusTitle"},{"id":"c-14-1-4","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"القلح","text":"السطوح الدهليزية المقابلة للرحى الأولى والثانية العلوية.","href":"page-14.html#calculusTitle"},{"id":"c-14-2-0","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"التلونات السنية في أمراض النسج الداعمة","text":"يطلق على الأصبغة الملونة التي تتوضع على سطوح الأسنان مسببة مشكلات تجميلية، وقد تصبح مع الوقت مصدر تخريش ثانوي. تحدث بسبب جراثيم مولدة للأصباغ، أو الأطعمة، أو بعض المنتجات الكيميائية، أو بسبب بشـرات سنية مكتسبة أو تطورية.","href":"page-14.html#stainTitle"},{"id":"c-14-2-1","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"التلونات السنية في أمراض النسج الداعمة","text":"تختلف التلونات في اللون و التركيب و شدة الالتصاق على السطح السني.","href":"page-14.html#stainTitle"},{"id":"c-14-2-2","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"التلونات السنية في أمراض النسج الداعمة","text":"يسبب التبغ فضلات سطحها صلب، ولونها كستنائي غامق أو أسود. كما ينجم التلون عن احتراق قطران الفحم الحجري ودخول عصير التبغ في شقوق الميناء والعاج.","href":"page-14.html#stainTitle"},{"id":"c-14-2-3","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"التلونات السنية في أمراض النسج الداعمة","text":"ليس من الضروري أن يتناسب الاصطباغ طرداً مع كمية استهلاك التبغ، لكنه يتعلق بدرجة كبيرة بالأغشية السنية الموجودة مسبقاً .","href":"page-14.html#stainTitle"},{"id":"c-14-2-4","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"التلونات السنية في أمراض النسج الداعمة","text":"قد تدخل بعض المعادن والأملاح المعدنية إلى الحفرة الفموية عند العاملين في الصناعة أو مع بعض الأدوية المتناولة فموياً، فتتحد مع الغلاف السني وتسبب لوناً سطحياً أو تدخل في المادة السنية فتحدث تلوناً دائماً.","href":"page-14.html#stainTitle"},{"id":"c-14-2-7","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"التلونات السنية في أمراض النسج الداعمة","text":"العقاقير الحاوية على ساليفت الحديد: فضلات سوداء.","href":"page-14.html#stainTitle"},{"id":"c-14-2-8","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"التلونات السنية في أمراض النسج الداعمة","text":"تلونات أخرى: منغنيز (أسود)، زئبق (أسود مخضر)، نيكل (أخضر)، فضة (أسود).","href":"page-14.html#stainTitle"},{"id":"c-14-2-9","type":"content","page":14,"pageTitle":"القلح والتلونات السنية","section":"التلونات السنية في أمراض النسج الداعمة","text":"تشترك هذه التلونات جميعها في قدرتها على الإسهام في إحداث مرض لثوي من خلال إيواء الجراثيم ومفرزاتها وما يرافق ذلك من تخريش اللثة وبدء مرضها ثانوياً.","href":"page-14.html#stainTitle"},{"id":"i-14-0","type":"image","page":14,"pageTitle":"القلح والتلونات السنية","section":"الصور والرسوم","text":"صورة تبين تراكم القلح على السطوح اللسانية للقواطع السفلية الصورة المقتطعة من المصدر توضح التوضع الشائع للقلح قرب مخرج اللعاب.","href":"page-14.html"},{"id":"i-14-1","type":"image","page":14,"pageTitle":"القلح والتلونات السنية","section":"الصور والرسوم","text":"صورة سريرية لتراكم القلح على الأسنان الأمامية الصورة المقتطعة من المصدر تعكس تراكمات قلحية واضحة على الأسنان الأمامية السفلية.","href":"page-14.html"},{"id":"c-15-0-0","type":"content","page":15,"pageTitle":"بخر الفم","section":"بخر الفم (Halitosis)","text":"بخر الفم هو الرائحة غير الطبيعية الخارجة من الفم. لا يكون الفم النظيف في الحالة الطبيعية ذا رائحة مزعجة، وإنما تنشأ الرائحة غالباً من تخمر الفضلات الغذائية المتبقية بين الأسنان وفي الحفر النخرة بفعل الجراثيم المختلفة.","href":"page-15.html"},{"id":"c-15-0-1","type":"content","page":15,"pageTitle":"بخر الفم","section":"بخر الفم (Halitosis)","text":"بخر الفم قد يكون عرضاً لمرض عام أو مشكلة موضعية داخل الفم، لذلك يتطلب تشخيص السبب أولاً.","href":"page-15.html"},{"id":"c-15-1-0","type":"content","page":15,"pageTitle":"بخر الفم","section":"ما هو بخر الفم؟","text":"تأتي الجراثيم إلى الفم بواسطة الغذاء والهواء، وسرعان ما تجد الوسط الملائم من غذاء وحرارة ورطوبة فتتكاثر سريعاً. وقد تنتج غازات وروائح مثل الإندول و السكاتول و البوتريسين فتُكسب الفم الرائحة النتنة، ويزيد ذلك مع الإهمال في تنظيف الفم.","href":"page-15.html#definitionTitle"},{"id":"c-15-1-1","type":"content","page":15,"pageTitle":"بخر الفم","section":"ما هو بخر الفم؟","text":"كما أن جفاف الفم يزيد من الرائحة، لذلك يكون أصحاب التنفس الفموي أو من لديهم نقص في اللعاب أكثر عرضة لبخر الفم.","href":"page-15.html#definitionTitle"},{"id":"c-15-1-2","type":"content","page":15,"pageTitle":"بخر الفم","section":"ما هو بخر الفم؟","text":"يُعد بخر الفم عرضاً وليس مرضاً قائماً بذاته. وعلى طبيب الأسنان أن يميز بين الأسباب الموضعية الفموية و الأسباب العامة المسؤولة عن الحالة.","href":"page-15.html#definitionTitle"},{"id":"c-15-1-3","type":"content","page":15,"pageTitle":"بخر الفم","section":"ما هو بخر الفم؟","text":"تختلف رائحة الفم تبعاً لأوقات النهار وكمية اللعاب المتدفق.","href":"page-15.html#definitionTitle"},{"id":"c-15-1-4","type":"content","page":15,"pageTitle":"بخر الفم","section":"ما هو بخر الفم؟","text":"تكون أشد في الصباح بسبب تناقص اللعاب أثناء النوم وتفسخ البقايا.","href":"page-15.html#definitionTitle"},{"id":"c-15-1-5","type":"content","page":15,"pageTitle":"بخر الفم","section":"ما هو بخر الفم؟","text":"تشتد أيضاً عند المصابين بآفات رئوية وعند من لديهم حليمات لسانية كثيفة مغطية للسان.","href":"page-15.html#definitionTitle"},{"id":"c-15-1-6","type":"content","page":15,"pageTitle":"بخر الفم","section":"ما هو بخر الفم؟","text":"الروائح الناجمة عن أسباب عامة خارج الفم لا تكفي فيها إزالة البقايا أو تحسين الصحة الفموية فقط، بل تحتاج إلى تقييم سببي ومعالجة من الطبيب المختص.","href":"page-15.html#definitionTitle"},{"id":"c-15-2-0","type":"content","page":15,"pageTitle":"بخر الفم","section":"تصنيف الأسباب المؤدية لبخر الفم","text":"أمراض الممرات التنفسية العلوية: مثل الزوائد الأنفية، التهاب اللوزتين، والتهاب الجيب الفكي.","href":"page-15.html#causesTitle"},{"id":"c-15-2-1","type":"content","page":15,"pageTitle":"بخر الفم","section":"تصنيف الأسباب المؤدية لبخر الفم","text":"أمراض الطرق التنفسية السفلية: أمراض الرغامى والقصبات والرئتين.","href":"page-15.html#causesTitle"},{"id":"c-15-2-2","type":"content","page":15,"pageTitle":"بخر الفم","section":"تصنيف الأسباب المؤدية لبخر الفم","text":"مواد أو مركبات تُطرح مع هواء الزفير: مثل بعض الأطعمة، السوائل، العلاجات، الثوم، الكحول، والمركبات المحتوية على اليود.","href":"page-15.html#causesTitle"},{"id":"c-15-2-3","type":"content","page":15,"pageTitle":"بخر الفم","section":"تصنيف الأسباب المؤدية لبخر الفم","text":"اضطرابات دموية أو استقلابية: مثل رائحة الأمونياك، الأجسام الكيتونية، ومرض السكري.","href":"page-15.html#causesTitle"},{"id":"c-15-2-4","type":"content","page":15,"pageTitle":"بخر الفم","section":"تصنيف الأسباب المؤدية لبخر الفم","text":"أمراض جهاز الهضم وبعض الأمراض الدموية والكلوية.","href":"page-15.html#causesTitle"},{"id":"c-15-2-5","type":"content","page":15,"pageTitle":"بخر الفم","section":"تصنيف الأسباب المؤدية لبخر الفم","text":"صحة فموية سيئة وانحصار فضلات الطعام بسبب سوء توضع الأسنان أو الأجهزة الصناعية أو التقويمية أو الكسور والنخور.","href":"page-15.html#causesTitle"},{"id":"c-15-2-6","type":"content","page":15,"pageTitle":"بخر الفم","section":"تصنيف الأسباب المؤدية لبخر الفم","text":"الآفات التنخرية وما يتلو الجراحة الفموية المرافقة لنزف فموي أو نخر نسجي.","href":"page-15.html#causesTitle"},{"id":"c-15-2-7","type":"content","page":15,"pageTitle":"بخر الفم","section":"تصنيف الأسباب المؤدية لبخر الفم","text":"أمراض الأسنان: كنخر السن وتموت اللب والخراجات السنية.","href":"page-15.html#causesTitle"},{"id":"c-15-2-8","type":"content","page":15,"pageTitle":"بخر الفم","section":"تصنيف الأسباب المؤدية لبخر الفم","text":"أمراض اللثة: كالتقيح السني والجيوب الرعوية، وما يترافق مع الانحلال الجرثومي للقيح.","href":"page-15.html#causesTitle"},{"id":"c-15-2-9","type":"content","page":15,"pageTitle":"بخر الفم","section":"تصنيف الأسباب المؤدية لبخر الفم","text":"أمراض الفم: كالتهاب الفم القُرحي والتغذّرية الفموية وغيرها من الآفات الفموية.","href":"page-15.html#causesTitle"},{"id":"c-15-3-0","type":"content","page":15,"pageTitle":"بخر الفم","section":"معالجة البخر ومضادات البخر","text":"تُجرى من قبل المختص عندما تكون الأسباب داخلة ضمن إطار الأمراض العامة. لذلك لا تكفي المعالجات الفموية الموضعية وحدها في هذه الحالات.","href":"page-15.html#treatmentTitle"},{"id":"c-15-3-1","type":"content","page":15,"pageTitle":"بخر الفم","section":"معالجة البخر ومضادات البخر","text":"يرتجع النفس الكريه فموياً غالباً بالعناية الجيدة بالصحة الفموية ومعالجة النسج اللثوية المريضة، وإزالة العوامل الموضعية التي تساعد على تجمع الفضلات، وتعليم المريض تنظيف المسافات بين الأسنان والأماكن التي تختبئ فيها الفضلات.","href":"page-15.html#treatmentTitle"},{"id":"c-15-3-2","type":"content","page":15,"pageTitle":"بخر الفم","section":"معالجة البخر ومضادات البخر","text":"كما قد تفيد الغسولات الفموية التي تحوي مواد تقلل عوامل النمو الجرثومي، لكن ذلك يكون عادة مؤقتاً إذا لم تُزَل جميع الأسباب المؤثرة.","href":"page-15.html#treatmentTitle"},{"id":"c-15-3-3","type":"content","page":15,"pageTitle":"بخر الفم","section":"معالجة البخر ومضادات البخر","text":"تعمل هذه الأدوية بتأثير كيميائي أو ميكانيكي بهدف تعديل التفاعلات الناتجة عن تفسخ المادة الأجنبية الفاغرة بين المسافات أو داخل الحفر النخرة أو الجيوب المرضية. وتشمل المواد المؤكسدة والماصة مثل الفحم و الكلوروفيل وبعض الأحماض ومشتقاتها والمواد التي تحرر الكلور .","href":"page-15.html#treatmentTitle"},{"id":"c-15-3-4","type":"content","page":15,"pageTitle":"بخر الفم","section":"معالجة البخر ومضادات البخر","text":"وظيفتها تخريب الفضلات وتعطيل البؤر الفموية السنية المؤدية للتفسخ، والقضاء على العوامل الجرثومية أو إيقاف نموها، مع تعديل الغازات الناجمة عنها وامتصاصها.","href":"page-15.html#treatmentTitle"},{"id":"i-15-0","type":"image","page":15,"pageTitle":"بخر الفم","section":"الصور والرسوم","text":"رسم يوضح الجراثيم على سطح اللسان ودورها في بخر الفم الصورة المقتطعة من المصدر تبيّن تراكم الجراثيم على اللسان باعتباره أحد المصادر المهمة للرائحة الفموية.","href":"page-15.html"},{"id":"c-16-0-0","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"العادات الفموية السيئة في أمراض النسج الداعمة","text":"تشمل هذه الصفحة أربع عادات أو حالات ذات أثر مهم في الفم والأسنان والنسج الداعمة، وهي: دفع اللسان ، التنفس الفموي ، مص الإصبع ، و التبغ . تؤثر هذه العادات في اتجاه القوى الإطباقية، تموضع الأسنان، صحة اللثة، وشكل القوسين السنيتين.","href":"page-16.html"},{"id":"c-16-0-1","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"العادات الفموية السيئة في أمراض النسج الداعمة","text":"كل عادة فموية سيئة تُقيَّم من حيث السبب، المظاهر السريرية، التأثير على الأسنان والنسج الداعمة، ثم الخطة العلاجية المناسبة.","href":"page-16.html"},{"id":"c-16-1-0","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"نظرة سريعة على المحاور","text":"يرتبطان غالباً بتبدل القوى المؤثرة على الأسنان الأمامية والفكين، وقد يسببان سوء إطباق، ميلان القواطع، التهابات لثوية، وضيق القوس العلوية.","href":"page-16.html#overviewTitle"},{"id":"c-16-1-1","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"نظرة سريعة على المحاور","text":"مص الإصبع من العادات الطفولية الشائعة وقد يؤدي إلى عضة مفتوحة وتضيق القوس. أما التبغ فيترافق مع تغيرات لونية ونسجية والتهابات وآفات أكثر شدة ضمن الفم.","href":"page-16.html#overviewTitle"},{"id":"c-16-2-0","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"دفع اللسان","text":"تسبب هذه العادة قوة دفع مستمرة على الأسنان، وغالباً على الأسنان الأمامية. تحدث عوضاً عن وضع ظهر اللسان بملامسة قبة الحنك، مع احتفاظ ذروة اللسان خلف الأسنان العلوية أثناء البلع على الأسنان الأمامية السفلية التي تنثني وتتباعد جانبياً.","href":"page-16.html#tongueTitle"},{"id":"c-16-2-1","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"دفع اللسان","text":"قد يسبب الدفع اللساني ضغطاً جانبياً شديداً يعرّض النسج المحيطة بالأسنان للأذى، كما قد يسبب افتتاحاً في المناطق الأمامية أو الخلفية من الإطباق.","href":"page-16.html#tongueTitle"},{"id":"c-16-2-2","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"دفع اللسان","text":"تشوه وميلان الأسنان الأمامية العلوية بسبب تغير اتجاه القوى الإطباقية.","href":"page-16.html#tongueTitle"},{"id":"c-16-2-3","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"دفع اللسان","text":"ازدياد الضغط الجانبي المطبق على التيجان.","href":"page-16.html#tongueTitle"},{"id":"c-16-2-4","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"دفع اللسان","text":"ضخامة الهجرة الشفوية وظهور دوران شفوي لساني غير مرغوب فيه.","href":"page-16.html#tongueTitle"},{"id":"c-16-2-5","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"دفع اللسان","text":"تضاد بين القوى الموجهة للأسنان شفوياً وضغط الشفة الداخلي، مما قد يسبب تحرك السن.","href":"page-16.html#tongueTitle"},{"id":"c-16-2-6","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"دفع اللسان","text":"المعالجة: وضع جهاز تقويمي يساعد الطفل على التعود على البلع الصحيح.","href":"page-16.html#tongueTitle"},{"id":"c-16-3-0","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التنفس الفموي","text":"انسداد المجاري التنفسية بشكل ولادي أو مكتسب.","href":"page-16.html#breathingTitle"},{"id":"c-16-3-1","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التنفس الفموي","text":"كسور أو رضوض أو انحرافات الوتيرة الأنفية.","href":"page-16.html#breathingTitle"},{"id":"c-16-3-2","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التنفس الفموي","text":"ضخامة القرينات الأنفية أو تورمها الالتهابي.","href":"page-16.html#breathingTitle"},{"id":"c-16-3-3","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التنفس الفموي","text":"وجود أورام عظمية أو ليفية في الحفرة الأنفية.","href":"page-16.html#breathingTitle"},{"id":"c-16-3-4","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التنفس الفموي","text":"ضخامة اللوزات أو الناسيات الغدية، واللسان العرطل الكبير.","href":"page-16.html#breathingTitle"},{"id":"c-16-3-5","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التنفس الفموي","text":"قد ترافقه عادة مص الإصبع.","href":"page-16.html#breathingTitle"},{"id":"c-16-3-6","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التنفس الفموي","text":"تضيق فوهة المنخرين، شحوب الوجه، الوهن الجسدي العام، وضيق التنفس الليلي والشخير.","href":"page-16.html#breathingTitle"},{"id":"c-16-3-7","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التنفس الفموي","text":"التهابات جيوب أنفية مزمنة أو زكام متكرر.","href":"page-16.html#breathingTitle"},{"id":"c-16-3-8","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التنفس الفموي","text":"نخور سنية معممة، التهابات لثوية بسبب جفاف الفم، ورائحة فم كريهة.","href":"page-16.html#breathingTitle"},{"id":"c-16-3-9","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التنفس الفموي","text":"وهَن في الشفاه يؤدي إلى ميلان القواطع العلوية دهليزياً.","href":"page-16.html#breathingTitle"},{"id":"c-16-3-10","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التنفس الفموي","text":"بروفيل وجه طويل ورفيع، ضيق القوس العلوية، وظهور العضة الخلفية المعكوسة.","href":"page-16.html#breathingTitle"},{"id":"c-16-3-11","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التنفس الفموي","text":"تراكب الأسنان العلوية أو انطمار بعضها.","href":"page-16.html#breathingTitle"},{"id":"c-16-3-12","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التنفس الفموي","text":"يبدأ بعلاج السبب المؤدي، مع إحالة المريض إلى اختصاصي أنف أذن حنجرة عند الحاجة.","href":"page-16.html#breathingTitle"},{"id":"c-16-3-13","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التنفس الفموي","text":"يمكن استخدام الشاشة الفموية الواقية ، وهي جهاز من صفيحة أكريلية يلامس السطوح الدهليزية للفكين أثناء النوم، ويساعد على التحول التدريجي إلى التنفس الأنفي.","href":"page-16.html#breathingTitle"},{"id":"c-16-4-0","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"منعكس المص هو النظام العصبي الباكر الذي يسمح للطفل بالرضاعة والالتصاق بالأم، وهو موجود منذ المراحل الأولى بعد الولادة. وعندما يُستبدل الإرضاع الطبيعي بالرضاعة الصناعية أو تُختصر مدة الرضاعة قد يضطر الطفل إلى مص الإصبع تعويضاً للنقص الحاصل.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-1","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"تنشأ عادة مص الإصبع خلال السنوات الأولى من عمر الطفل.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-2","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"يمارسها نسبة ملحوظة من الأطفال.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-3","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"يمكن أن يبدأ العلاج بعمر 5 سنوات تقريباً.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-4","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"العامل النفسي والاجتماعي ونقص حنان الأم.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-6","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"ولادة طفل جديد في العائلة أو الاهتمام الزائد به.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-7","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"عدم كفاية حليب الأم أو عدم الاستعاضة بالحليب الصناعي وشعور الطفل بالجوع.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-8","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"موقف الأهل غير المتفهم لطبيعة العادة وأسباب لجوء الطفل إليها.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-9","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"بروز سني علوي وميلان الأسنان الأمامية العلوية دهليزياً.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-10","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"تراجع سني سفلي وميلان الأسنان الأمامية السفلية لسانياً.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-11","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"فراغ بين الأسنان الأمامية العلوية والسفلية (العضة المفتوحة).","href":"page-16.html#thumbTitle"},{"id":"c-16-4-12","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"تضيق في القوس السنية العلوية قد يجعلها على شكل حرف V.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-13","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"قد تظهر العضة الخلفية المعكوسة ومشاكل في النطق وتشوه الإصبع.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-14","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"تتأثر الشدة بوضع الإصبع، مدة استمرار العادة، وعدد ساعات ممارستها خاصة أثناء النوم.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-15","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"غالباً ما يحدث تصحيح عفوي للعضة المفتوحة بعد زوال العادة، أما استمرارها بعد 8 سنوات فقد يحتاج إلى تصحيح الخلل المتشكل.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-16","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"التخلص من العادة يحتاج إلى تعاون طبيب الأسنان وطبيب الأطفال والأخصائي النفسي والأهل.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-17","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"التوعية: شرح أثر العادة على الطفل وتفهّم مشكلته وتأمين الحنان والطمأنينة.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-18","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"وسائل التذكير: كربط الإصبع أو وضع طلاء سيئ الطعم، مع الحذر من الأساليب العنيفة.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-19","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"المكافأة: تشجيع الطفل عند التوقف عن العادة.","href":"page-16.html#thumbTitle"},{"id":"c-16-4-20","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"مص الإصبع","text":"الوسائل الميكانيكية: أجهزة تقويمية مثل كابح اللسان أو الأكتيفاتور.","href":"page-16.html#thumbTitle"},{"id":"c-16-5-0","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التبغ","text":"لا يسبب التدخين عادة تغيرات لثوية واضحة بذاته فقط، لكن الحرارة وتجمع نواتج الاحتراق يمثلان مخرشين موضعيين . كما يمكن ملاحظة تبدلات فموية مهمة عند المدخنين.","href":"page-16.html#smokingTitle"},{"id":"c-16-5-1","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التبغ","text":"تتدرج التبدلات من فضلات سمراء تشبه القطران وتلون الأسنان إلى تغيرات منتشرة في اللثة والمخاطية، مع ازدياد شدة الإصابات النسجية لدى المدخنين.","href":"page-16.html#smokingTitle"},{"id":"c-16-5-2","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التبغ","text":"فضلات سمراء تشبه القطران وتلون الأسنان.","href":"page-16.html#smokingTitle"},{"id":"c-16-5-3","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التبغ","text":"قبة حنك المدخن تتميز ببروز الغدد المخاطية المترافق بالتهاب فوهاتها وبقع وردية منتشرة.","href":"page-16.html#smokingTitle"},{"id":"c-16-5-4","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التبغ","text":"تلون مائل للرمادي منتشر، وإصابة اللثة بالطلواة.","href":"page-16.html#smokingTitle"},{"id":"c-16-5-5","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التبغ","text":"قد يسبب مسك الغليون في موضع واحد انحلالاً سنياً مع تشكل فراغ هلالي بين الأسنان، وازحاماً أو انغراساً للأسنان، وتغيرات مرضية في النسج الداعمة.","href":"page-16.html#smokingTitle"},{"id":"c-16-5-6","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التبغ","text":"لوحظ انتشار متزايد لالتهاب لثوي مزمن والتهاب لثوي تقرحي تموتي حاد لدى المدخنين.","href":"page-16.html#smokingTitle"},{"id":"c-16-5-7","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التبغ","text":"زيادة انتشار وشدة الإصابات السنية السطحية وتجمع اللويحة الجرثومية والقلح بشكل أكبر.","href":"page-16.html#smokingTitle"},{"id":"c-16-5-8","type":"content","page":16,"pageTitle":"العادات الفموية السيئة","section":"التبغ","text":"يزداد عدد الخلايا اللثوية المتقرنة عند المدخنين، مع تغيرات أخرى في مخاطية الفم باستثناء تشوه استهلاك الأكسجين.","href":"page-16.html#smokingTitle"},{"id":"i-16-0","type":"image","page":16,"pageTitle":"العادات الفموية السيئة","section":"الصور والرسوم","text":"جهاز تقويمي للمساعدة في تصحيح عادة دفع اللسان وسيلة علاجية تقويمية تُستخدم لتوجيه اللسان وتعليم البلع الصحيح.","href":"page-16.html"},{"id":"i-16-1","type":"image","page":16,"pageTitle":"العادات الفموية السيئة","section":"الصور والرسوم","text":"جهاز علاجي آخر لتصحيح دفع اللسان مثال ثانٍ يُظهر نفس المبدأ العلاجي في منع الدفع اللساني غير الطبيعي.","href":"page-16.html"},{"id":"i-16-2","type":"image","page":16,"pageTitle":"العادات الفموية السيئة","section":"الصور والرسوم","text":"الشاشة الفموية الواقية المستخدمة في علاج التنفس الفموي الشاشة الفموية الواقية جهاز يساعد على تدريب المريض على التنفس الأنفي تدريجياً.","href":"page-16.html"},{"id":"i-16-3","type":"image","page":16,"pageTitle":"العادات الفموية السيئة","section":"الصور والرسوم","text":"رسم توضيحي مرتبط بالتنفس الفموي أو الشاشة الفموية توضيح تشريحي/وظيفي يوضح شكل الجهاز وعلاقته بالفك أو المجرى التنفسي.","href":"page-16.html"},{"id":"i-16-4","type":"image","page":16,"pageTitle":"العادات الفموية السيئة","section":"الصور والرسوم","text":"طفل يمص الإصبع صورة سريرية عامة توضح الممارسة الشائعة للعلاقة بين المص والطمأنة الذاتية عند الطفل.","href":"page-16.html"},{"id":"i-16-5","type":"image","page":16,"pageTitle":"العادات الفموية السيئة","section":"الصور والرسوم","text":"سوء إطباق ناتج عن عادة مص الإصبع أثر سريري على الإطباق يظهر بروز القواطع والفراغ الأمامي الناجمين عن مص الإصبع.","href":"page-16.html"},{"id":"i-16-6","type":"image","page":16,"pageTitle":"العادات الفموية السيئة","section":"الصور والرسوم","text":"جهاز تقويمي للمساعدة في وقف مص الإصبع جهاز علاجي 1 وسيلة ميكانيكية لتعديل السلوك الفموي الضار.","href":"page-16.html"},{"id":"i-16-7","type":"image","page":16,"pageTitle":"العادات الفموية السيئة","section":"الصور والرسوم","text":"مثال آخر على جهاز تقويمي ضد عادة مص الإصبع جهاز علاجي 2 مثال إضافي للوسائل التقويمية المساعدة.","href":"page-16.html"},{"id":"c-17-0-0","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"نخر الأسنان: الأسباب، العوامل، وتطور المراحل","text":"يعد نخر الأسنان من أوسع الأمراض انتشاراً، وقد تتجاوز نسبة انتشاره في بعض البلاد 90% من السكان. ويتسع هذا المرض مع ارتفاع مستوى الحضارة والمدنية، إذ يرتبط بعادات غذائية وسلوكية تزيد من فرصة حدوثه.","href":"page-17.html"},{"id":"c-17-0-1","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"نخر الأسنان: الأسباب، العوامل، وتطور المراحل","text":"لفهم النخر يجب ربط العامل الجرثومي مع نوع الغذاء و قابلية السن ، ثم تتبع تطور الإصابة من الميناء حتى اللب.","href":"page-17.html"},{"id":"c-17-1-0","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تعريف مختصر وصورة سريرية","text":"إن الأسباب الحقيقية المؤدية للإصابة بالنخر لا تزال غير مفهومة تماماً، لكن أقرب النظريات المقبولة هي نظرية تكون الحموض ، ومفادها أن الجراثيم تحول بقايا الطعام الغنية بالسكريات إلى أحماض، وهذه الأحماض تحل النسج السنية المعدنية، ثم يتخرب هيكل السن العضوي في مرحلة لاحقة.","href":"page-17.html#introTitle"},{"id":"c-17-1-1","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تعريف مختصر وصورة سريرية","text":"ولكي يحدث النخر السني لا بد من توافر ثلاثة عوامل أساسية: السن ، الجراثيم ، و الغذاء .","href":"page-17.html#introTitle"},{"id":"c-17-2-0","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"أسباب النخر والعوامل الأساسية","text":"لا يحدث النخر من دون وجود سطح سنّي، لكن قابلية السن تختلف باختلاف البنية والتركيب ودرجة المقاومة، وتُذكر هذه العوامل لاحقاً ضمن العوامل العامة والموضعية.","href":"page-17.html#causesTitle"},{"id":"c-17-2-1","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"أسباب النخر والعوامل الأساسية","text":"يولد الطفل وفمه خالٍ من الجراثيم، ثم يصبح حاوياً لها خلال الأشهر الأولى. تتجمع الجراثيم ضمن هيكل عضوي يضم بروتينات وشحوماً وسكريات متعددة، ويُعرف هذا التجمع باسم اللويحات الجرثومية . تستفيد الجراثيم من السكريات المتناولة، ولا سيما السكر ثنائي السكروز ، فتفككه إلى سكريات أحادية وتُنتج أحماضاً تزيل تمعدن النسج السنية.","href":"page-17.html#causesTitle"},{"id":"c-17-2-2","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"أسباب النخر والعوامل الأساسية","text":"لذلك فإن تنظيف الفم بالفرشاة والخيط يعرقل نمو اللويحات الجرثومية ويزيلها، وتشكّل النظافة الفموية المقاومة المادية لهذه اللويحات.","href":"page-17.html#causesTitle"},{"id":"c-17-2-3","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"أسباب النخر والعوامل الأساسية","text":"يقصد بالغذاء هنا الغنى بالسكريات ، إذ يمكن أن تتحول هذه الأخيرة إلى أحماض بتأثير الجراثيم الفموية، وتزداد نسبة حدوث النخر طرداً مع زيادة استهلاك السكر.","href":"page-17.html#causesTitle"},{"id":"c-17-2-4","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"أسباب النخر والعوامل الأساسية","text":"الشكل الفيزيائي: إذا كانت السكريات لاصقة بقيت في الفم مدة أطول فزادت خطورتها، أما المحاليل فتبقى أقل زمناً من المنتجات الصلبة اللاصقة.","href":"page-17.html#causesTitle"},{"id":"c-17-2-5","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"أسباب النخر والعوامل الأساسية","text":"الزمن المستغرق في الاستهلاك: تناول كمية محدودة في فترة قصيرة أقل ضرراً من تناول المقدار نفسه لفترة طويلة.","href":"page-17.html#causesTitle"},{"id":"c-17-2-6","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"أسباب النخر والعوامل الأساسية","text":"نوع السكر: ينتشر السكروز بسرعة في اللويحات الجرثومية، بينما تكون النشويات أبطأ انتشاراً.","href":"page-17.html#causesTitle"},{"id":"c-17-2-7","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"أسباب النخر والعوامل الأساسية","text":"المواد الممزوجة معه: وجود مواد مضادة للنخر مثل الدسم أو الفول والشوكولا قد يُنقص من شدة التأثير الضار لبعض المنتجات السكرية.","href":"page-17.html#causesTitle"},{"id":"c-17-2-8","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"أسباب النخر والعوامل الأساسية","text":"عند تناول السكريات بين الوجبات الرئيسية يكون اللعاب قبل الوجبة قريباً من الاعتدال ، ثم ينخفض بعد تناول السكر ويستمر في هذا الانخفاض عدة دقائق قبل أن يعود تدريجياً. تتكرر هذه الحلقة عند كثرة الوجبات الصغيرة السكرية، فتطول مرحلة انحلال الأملاح المعدنية وتزداد سرعة انتشار النخر.","href":"page-17.html#causesTitle"},{"id":"c-17-2-9","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"أسباب النخر والعوامل الأساسية","text":"تشير الدراسات إلى أن تناول السكريات في نهاية أو أثناء الوجبة الرئيسية أقل ضرراً مما لو تناولها الطفل منفصلة بين الوجبات، لذلك يُنصح بإعطاء الطفل مواد غير مهيئة للنخر كالفواكه أو اللوز أو الفستق عند الحاجة.","href":"page-17.html#causesTitle"},{"id":"c-17-3-0","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"عوامل النخر","text":"الوراثة: تلعب دوراً في قابلية النخر كما في بعض الأمراض العامة.","href":"page-17.html#factorsTitle"},{"id":"c-17-3-1","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"عوامل النخر","text":"العمر: تقل قابلية النخر مع تقدم العمر، أما الأسنان اللبنية فتكون شديدة المقاومة بدايةً ثم تقل هذه المقاومة لاحقاً.","href":"page-17.html#factorsTitle"},{"id":"c-17-3-2","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"عوامل النخر","text":"الجنس: للحمل والإرضاع أثر يجعل المرأة أكثر تعرضاً للنخر من الرجل.","href":"page-17.html#factorsTitle"},{"id":"c-17-3-3","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"عوامل النخر","text":"الغذاء: مهم عند الحامل، وعند الطفل خلال تشكل الأسنان وبدايات العمر.","href":"page-17.html#factorsTitle"},{"id":"c-17-3-4","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"عوامل النخر","text":"الهرمونات: مثل تأثير فرط نشاط الدرق في زيادة زوال الكلس من الأسنان.","href":"page-17.html#factorsTitle"},{"id":"c-17-3-5","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"عوامل النخر","text":"الفيتامينات: نقص (A) و(C) والكالسيوم والفسفور قد يسيء إلى بنية الأسنان والنسج المخاطية.","href":"page-17.html#factorsTitle"},{"id":"c-17-3-6","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"عوامل النخر","text":"الأمراض العامة: خاصة الأمراض المرافقة لزوال الكلس من الجسم أو سوء الهضم أو الحمى التيفية وغيرها.","href":"page-17.html#factorsTitle"},{"id":"c-17-3-7","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"عوامل النخر","text":"موقع السن: الأسنان الأمامية السفلية أقل عرضة نسبياً، بينما الأرحاء والضواحك أكثر تعرضاً بسبب اتساع السطوح وكونها طاحنة.","href":"page-17.html#factorsTitle"},{"id":"c-17-3-8","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"عوامل النخر","text":"موقع النخر: ينتشر أكثر في السطوح ذات الوهد والشقوق وعلى الأسطح التي تنحصر فيها الفضلات.","href":"page-17.html#factorsTitle"},{"id":"c-17-3-9","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"عوامل النخر","text":"سوء التوضع: يزيد قابلية الإصابة بالنخر نتيجة فقدان نقطة التماس وانحصار الأطعمة في المسافات الضيقة.","href":"page-17.html#factorsTitle"},{"id":"c-17-3-10","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"عوامل النخر","text":"انسحال الأسنان: يؤدي إلى زوال الميناء وانكشاف العاج وحدوث النخر فيه.","href":"page-17.html#factorsTitle"},{"id":"c-17-3-11","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"عوامل النخر","text":"الجراثيم الفموية: تجد في الفم وسطاً ملائماً لنموها وتكاثرها من حيث الحرارة والرطوبة والغذاء.","href":"page-17.html#factorsTitle"},{"id":"c-17-3-12","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"عوامل النخر","text":"الأجهزة الصناعية: سوء الانطباق أو تراكم الفضلات على البدلات السنية أو الأجزاء الأكريلية قد يسبب النخر في الظروف نفسها.","href":"page-17.html#factorsTitle"},{"id":"c-17-3-13","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"عوامل النخر","text":"العامل الشخصي: تفاوت قابلية الأسنان للنخر بين أشخاص يعيشون في بيئة وظروف معيشية متشابهة.","href":"page-17.html#factorsTitle"},{"id":"c-17-4-0","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تطور النخر ومراحله","text":"يبدأ النخر من خارج السن في مناطق مختارة كالوهاد والشقوق الواقعة على السطوح الطاحنة أو اللسانية، كما يبدأ أحياناً بين الأسنان أو من الناحية اللثوية حيث لا يطالها التنظيف الغريزي بحركات الخدين والشفتين واللسان.","href":"page-17.html#stagesTitle"},{"id":"c-17-4-1","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تطور النخر ومراحله","text":"يبدأ بشكل بدئي بسيط يصيب الميناء ويتحول لون المنطقة إلى الأسمر أو البني الغامق أو الأسود. يأخذ النخر في الشقوق والوهاد شكلاً مخروطياً ذروته خارجية وقاعدته داخلية، بينما يكون المخروط في السطوح الملساء معكوساً.","href":"page-17.html#stagesTitle"},{"id":"c-17-4-2","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تطور النخر ومراحله","text":"لا تترافق هذه المرحلة عادةً بأعراض تنبه المريض حتى يصل النخر إلى العاج.","href":"page-17.html#stagesTitle"},{"id":"c-17-4-3","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تطور النخر ومراحله","text":"عندما يصل النخر إلى العاج يزداد معدل الانتشار بسبب زيادة نسبة المواد العضوية فيه وقلة مقاومته. يتجه النخر نحو مركز السن متبعاً الأنابيب العاجية، ويتجه جانبياً متبعاً خط الاتصال المينائي العاجي.","href":"page-17.html#stagesTitle"},{"id":"c-17-4-4","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تطور النخر ومراحله","text":"يترافق نخر العاج بألم مثار بالماء البارد أو الساخن وبالمشروبات أو المواد الحامضة أو السكرية، وينجم ذلك عن تأثر ألياف تنطلق من اللب حتى ملتقى الميناء بالعاج.","href":"page-17.html#stagesTitle"},{"id":"c-17-4-5","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تطور النخر ومراحله","text":"بعد تجاوز النخر للميناء والعاج ووصوله إلى مشارف اللب تبدأ أعراض التهاب اللب، وهو ألم شديد ومبرح بسبب زيادة التروية والضغط داخل النسج المحاطة بجدران صلبة.","href":"page-17.html#stagesTitle"},{"id":"c-17-4-6","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تطور النخر ومراحله","text":"ألم مثار بالمهيجات: يزداد مع اشتداد النخر العاجي.","href":"page-17.html#stagesTitle"},{"id":"c-17-4-7","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تطور النخر ومراحله","text":"ألم عفوي: يأتي على شكل نوبات شديدة متناوبة مع فترات هدوء، ويشتد ليلاً.","href":"page-17.html#stagesTitle"},{"id":"c-17-4-8","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تطور النخر ومراحله","text":"تنبيه سريري مهم: لا يفيد وضع المسكنات أو الأدوية الكاوية مباشرةً على السن، بل قد يسبب أذى للثة.","href":"page-17.html#stagesTitle"},{"id":"c-17-4-9","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تطور النخر ومراحله","text":"قد يستدعي وصول الجراثيم إلى اللب استئصال كامل النسيج اللبي أو معالجته اللبية المناسبة.","href":"page-17.html#stagesTitle"},{"id":"c-17-4-10","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تطور النخر ومراحله","text":"إذا لم تُجر المعالجة في الوقت المناسب قد يمتد الإنتان إلى النسج المحيطة بالسن ويتشكل خراج سني حاد أو آفات ذروية مزمنة.","href":"page-17.html#stagesTitle"},{"id":"c-17-4-11","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تطور النخر ومراحله","text":"الأسنان ذات الألباب الميتة يتغير لونها إلى القتامة وتصبح أكثر هشاشة، وقد تحتاج في كثير من الحالات إلى تتويج .","href":"page-17.html#stagesTitle"},{"id":"c-17-4-12","type":"content","page":17,"pageTitle":"نخر الأسنان","section":"تطور النخر ومراحله","text":"عند فقد كمية كبيرة من النسج السنية قد يلزم استخدام وتد وقلب معدني قبل التتويج.","href":"page-17.html#stagesTitle"},{"id":"i-17-0","type":"image","page":17,"pageTitle":"نخر الأسنان","section":"الصور والرسوم","text":"صورة سريرية لحالة نخر أسنان مثال سريري تُظهر الصورة آفات نخرية متعددة على الأسنان الأمامية.","href":"page-17.html"},{"id":"q-p01-q01","type":"question","page":1,"pageTitle":"الفك العلوي","section":"بنك الأسئلة","text":"ممّ يتألف الفك العلوي؟","extra":"الفك العلوي عظم مزدوج يتكوّن من عظمتين: يمنى ويسرى، تتحدان في الخط المتوسط.","href":"comprehensive-exam.html"},{"id":"q-p01-q02","type":"question","page":1,"pageTitle":"الفك العلوي","section":"بنك الأسئلة","text":"أين يلتقي عظما الفك العلوي الأيمن والأيسر؟","extra":"يحدث الاتحاد على الدرز المتوسط (Median suture) في منتصف الفك العلوي.","href":"comprehensive-exam.html"},{"id":"q-p01-q03","type":"question","page":1,"pageTitle":"الفك العلوي","section":"بنك الأسئلة","text":"الناتئان الحنكيان الأفقيان يلتقيان في الخط المتوسط.","extra":"صحيح، ويلعب هذا الالتقاء دوراً أساسياً في تكوين الحنك الصلب.","href":"comprehensive-exam.html"},{"id":"q-p01-q04","type":"question","page":1,"pageTitle":"الفك العلوي","section":"بنك الأسئلة","text":"ما البنيتان اللتان يسهم الناتئان الحنكيان في تشكيلهما؟","extra":"يشكّل الناتئان الحنكيان جزءاً كبيراً من الحنك الصلب، أي سقف الفم، ويقابلانه من الأعلى قاع الحفرة الأنفية.","href":"comprehensive-exam.html"},{"id":"q-p01-q05","type":"question","page":1,"pageTitle":"الفك العلوي","section":"بنك الأسئلة","text":"ماذا تحتوي النواتئ السنخية؟","extra":"النواتئ السنخية تحوي الأسناخ السنية (Alveoli) التي تستقر فيها جذور الأسنان.","href":"comprehensive-exam.html"},{"id":"q-p01-q06","type":"question","page":1,"pageTitle":"الفك العلوي","section":"بنك الأسئلة","text":"العمل الصناعي السني يتوضع في منطقة معزولة ولا يتأثر بما يحيط بها.","extra":"خطأ؛ التعويض السني يتوضع في منطقة حيوية ويتبادل التأثيرات مع النسج والبنى المحيطة.","href":"comprehensive-exam.html"},{"id":"q-p02-q01","type":"question","page":2,"pageTitle":"الفك السفلي","section":"بنك الأسئلة","text":"ما الوصف الأدق للفك السفلي؟","extra":"الفك السفلي عظم مفرد ذو شكل قريب من نعل الفرس.","href":"comprehensive-exam.html"},{"id":"q-p02-q02","type":"question","page":2,"pageTitle":"الفك السفلي","section":"بنك الأسئلة","text":"ممّ يتألف الفك السفلي بصورة أساسية؟","extra":"يتكون من جسم أفقي يحمل الأسنان ومن شعبتين صاعدتين على الجانبين.","href":"comprehensive-exam.html"},{"id":"q-p02-q03","type":"question","page":2,"pageTitle":"الفك السفلي","section":"بنك الأسئلة","text":"الفك السفلي هو العظم المتحرك الوحيد من عظام الجمجمة.","extra":"صحيح؛ تتحقق حركته عبر المفصلين الفكيين الصدغيين.","href":"comprehensive-exam.html"},{"id":"q-p02-q04","type":"question","page":2,"pageTitle":"الفك السفلي","section":"بنك الأسئلة","text":"بأي جزء يرتبط الفك السفلي بالجمجمة؟","extra":"ترتبط لقمتا الفك السفلي بالعظم الصدغي ضمن المفصل الفكي الصدغي (TMJ).","href":"comprehensive-exam.html"},{"id":"q-p02-q05","type":"question","page":2,"pageTitle":"الفك السفلي","section":"بنك الأسئلة","text":"أي بنية تقع على السطح الخارجي لجسم الفك وتظهر في المنظر الوحشي؟","extra":"الثقبة الذقنية (Mental foramen) تُشاهد على السطح الخارجي لجسم الفك السفلي.","href":"comprehensive-exam.html"},{"id":"q-p02-q06","type":"question","page":2,"pageTitle":"الفك السفلي","section":"بنك الأسئلة","text":"الناتئ اللقمي هو نفسه الناتئ الإكليلي.","extra":"خطأ؛ الناتئ اللقمي يشارك في المفصل، أما الناتئ الإكليلي فهو موضع ارتكاز عضلي.","href":"comprehensive-exam.html"},{"id":"q-p03-q01","type":"question","page":3,"pageTitle":"مخاطية الفم","section":"بنك الأسئلة","text":"أين تقع مخاطية الفم ضمن الجسم؟","extra":"تقع مخاطية الفم في بداية جهاز الهضم وتُعد جزءاً مهماً منه.","href":"comprehensive-exam.html"},{"id":"q-p03-q02","type":"question","page":3,"pageTitle":"مخاطية الفم","section":"بنك الأسئلة","text":"قد تتظاهر في مخاطية الفم علامات بعض الأمراض العامة وأمراض جهاز الهضم.","extra":"صحيح؛ لذلك وُصفت في النص بأنها تشبه ميزان العضوية الحساس.","href":"comprehensive-exam.html"},{"id":"q-p03-q03","type":"question","page":3,"pageTitle":"مخاطية الفم","section":"بنك الأسئلة","text":"ما الذي يساعد مخاطية الفم في الدفاع ضد العوامل الخارجية؟","extra":"تسهم خلايا المخاطية المختلفة واللعاب الذي تفرزه الغدد في الحماية والدفاع.","href":"comprehensive-exam.html"},{"id":"q-p03-q04","type":"question","page":3,"pageTitle":"مخاطية الفم","section":"بنك الأسئلة","text":"تتميز مخاطية الفم بقدرة كبيرة على التندب والترميم.","extra":"صحيح؛ من خصائصها المهمة قدرتها العالية على التعافي والترميم.","href":"comprehensive-exam.html"},{"id":"q-p03-q05","type":"question","page":3,"pageTitle":"مخاطية الفم","section":"بنك الأسئلة","text":"ممّ تتكون الشفتان بحسب النص؟","extra":"الشفتان نسيج عضلي متحرك يشكّل غطاء الأسنان.","href":"comprehensive-exam.html"},{"id":"q-p03-q06","type":"question","page":3,"pageTitle":"مخاطية الفم","section":"بنك الأسئلة","text":"كم يبلغ طول الخط الشفوي وسطياً؟","extra":"ورد في الصفحة أن طول الخط الشفوي يبلغ 5 سم وسطياً وقد يختلف بين الأشخاص.","href":"comprehensive-exam.html"},{"id":"q-p04-q01","type":"question","page":4,"pageTitle":"الخد والحنك واللسان","section":"بنك الأسئلة","text":"ما علاقة الغشاء المخاطي المبطن للخد بالغشاء المخاطي الشفوي؟","extra":"الغشاء المخاطي المبطن للخد هو امتداد للغشاء المخاطي الشفوي وله البنية نفسها.","href":"comprehensive-exam.html"},{"id":"q-p04-q02","type":"question","page":4,"pageTitle":"الخد والحنك واللسان","section":"بنك الأسئلة","text":"ما الوظيفة التشريحية الأساسية لسقف الفم؟","extra":"يشكل سقف الفم حاجزاً بين حفرة الفم والحفرتين الأنفيتين.","href":"comprehensive-exam.html"},{"id":"q-p04-q03","type":"question","page":4,"pageTitle":"الخد والحنك واللسان","section":"بنك الأسئلة","text":"أي جزء يشكل القسم الأمامي من قبة الحنك؟","extra":"قبة الحنك الصلبة هي الجزء الأمامي، ويدخل في تشكيلها أربعة عظام.","href":"comprehensive-exam.html"},{"id":"q-p04-q05","type":"question","page":4,"pageTitle":"الخد والحنك واللسان","section":"بنك الأسئلة","text":"ما اسم البروز المتدلي من الحنك الرخو نحو الأسفل؟","extra":"تنتهي قبة الحنك الرخوة ببروز متدلٍ يسمى اللهاة.","href":"comprehensive-exam.html"},{"id":"q-p04-q06","type":"question","page":4,"pageTitle":"الخد والحنك واللسان","section":"بنك الأسئلة","text":"ماذا يحدث لشراع الحنك أثناء البلع؟","extra":"تتقلص عضلاته المخططة فتشده إلى الأعلى والخلف لإغلاق فوهة البلعوم الأنفي.","href":"comprehensive-exam.html"},{"id":"q-p04-q07","type":"question","page":4,"pageTitle":"الخد والحنك واللسان","section":"بنك الأسئلة","text":"كم عضلة يتكون منها اللسان بحسب النص؟","extra":"ورد في الصفحة أن اللسان عضو عضلي مكوّن من 17 عضلة.","href":"comprehensive-exam.html"},{"id":"q-p04-q09","type":"question","page":4,"pageTitle":"الخد والحنك واللسان","section":"بنك الأسئلة","text":"أي الحليمات لا تحتوي على براعم الذوق بحسب النص؟","extra":"توجد براعم الذوق في الحليمات اللسانية جميعها عدا الحليمات الخيطية.","href":"comprehensive-exam.html"},{"id":"q-p05-q01","type":"question","page":5,"pageTitle":"الغدد اللعابية","section":"بنك الأسئلة","text":"أي وظيفة ذُكرت للّعاب في الصفحة؟","extra":"يسهّل اللعاب المضغ والبلع، ويسهم في هضم بعض عناصر الطعام.","href":"comprehensive-exam.html"},{"id":"q-p05-q03","type":"question","page":5,"pageTitle":"الغدد اللعابية","section":"بنك الأسئلة","text":"ما أكبر الغدد اللعابية؟","extra":"الغدة النكفية هي أكبر الغدد اللعابية.","href":"comprehensive-exam.html"},{"id":"q-p05-q05","type":"question","page":5,"pageTitle":"الغدد اللعابية","section":"بنك الأسئلة","text":"أين يتوضع القسم الأكبر من الغدة تحت الفك؟","extra":"يتوضع القسم الأكبر في المنطقة تحت الفكية خلف وأسفل العضلة الضرسية اللامية.","href":"comprehensive-exam.html"},{"id":"q-p05-q06","type":"question","page":5,"pageTitle":"الغدد اللعابية","section":"بنك الأسئلة","text":"أين تفتح قناة وارتون؟","extra":"تفتح قناة وارتون في أرض الفم على طرفي لجام اللسان.","href":"comprehensive-exam.html"},{"id":"q-p05-q07","type":"question","page":5,"pageTitle":"الغدد اللعابية","section":"بنك الأسئلة","text":"إلى أي غدة تنتمي قناة بارتولين؟","extra":"قناة بارتولين هي القناة المفرغة للغدة تحت اللسان بحسب المصدر.","href":"comprehensive-exam.html"},{"id":"q-p05-q09","type":"question","page":5,"pageTitle":"الغدد اللعابية","section":"بنك الأسئلة","text":"أي غدد تسهم بالنسبة الأكبر من الإفراز اللعابي الوسطي؟","extra":"النسب الواردة: تحت الفك 69%، النكفية 26%، وتحت اللسان 5%.","href":"comprehensive-exam.html"},{"id":"q-p06-q01","type":"question","page":6,"pageTitle":"الأسنان والبزوغ","section":"بنك الأسئلة","text":"كم عدد الأسنان المؤقتة في الفم؟","extra":"الأسنان المؤقتة عشرون: عشرة في كل فك وخمسة في كل جانب.","href":"comprehensive-exam.html"},{"id":"q-p06-q02","type":"question","page":6,"pageTitle":"الأسنان والبزوغ","section":"بنك الأسئلة","text":"متى تبدأ الأسنان الدائمة بالظهور غالباً؟","extra":"تبدأ المجموعة الدائمة عادةً بالظهور قرب السنة السادسة.","href":"comprehensive-exam.html"},{"id":"q-p06-q04","type":"question","page":6,"pageTitle":"الأسنان والبزوغ","section":"بنك الأسئلة","text":"ما موعد بزوغ الثنايا اللبنية السفلية بحسب الجدول؟","extra":"الثنايا السفلية اللبنية تبزغ بين 6 و10 أشهر.","href":"comprehensive-exam.html"},{"id":"q-p06-q05","type":"question","page":6,"pageTitle":"الأسنان والبزوغ","section":"بنك الأسئلة","text":"ما سبب أهمية بقاء السن اللبنية حتى موعد سقوطها الطبيعي؟","extra":"السن اللبنية تحفظ المسافة وتساعد في توجيه السن الدائمة القادمة.","href":"comprehensive-exam.html"},{"id":"q-p06-q07","type":"question","page":6,"pageTitle":"الأسنان والبزوغ","section":"بنك الأسئلة","text":"أي عبارة أدق بحسب المصدر حول الأعراض العامة المنسوبة للتسنين؟","extra":"البزوغ عملية فيزيولوجية، وقد تكون الأعراض العامة متزامنة أو مرتبطة بعوامل أخرى.","href":"comprehensive-exam.html"},{"id":"q-p06-q08","type":"question","page":6,"pageTitle":"الأسنان والبزوغ","section":"بنك الأسئلة","text":"كم عدد الأسنان الدائمة؟","extra":"العدد الكامل للأسنان الدائمة هو 32 سناً.","href":"comprehensive-exam.html"},{"id":"q-p06-q10","type":"question","page":6,"pageTitle":"الأسنان والبزوغ","section":"بنك الأسئلة","text":"ما أول الأرحاء الدائمة بزوغاً عادةً؟","extra":"الرحى الدائمة الأولى تبزغ عادةً بين 6 و7 سنوات.","href":"comprehensive-exam.html"},{"id":"q-p06-q11","type":"question","page":6,"pageTitle":"الأسنان والبزوغ","section":"بنك الأسئلة","text":"أين تظهر السن الزائدة الأكثر شيوعاً المذكورة في المصدر؟","extra":"السن الأنسيّة الزائدة تظهر غالباً بين القواطع المركزية العلوية.","href":"comprehensive-exam.html"},{"id":"q-p06-q13","type":"question","page":6,"pageTitle":"الأسنان والبزوغ","section":"بنك الأسئلة","text":"لماذا قد تكون السن الولادية متحركة؟","extra":"الحركة ترتبط غالباً بعدم اكتمال نمو الجذر.","href":"comprehensive-exam.html"},{"id":"q-p06-q14","type":"question","page":6,"pageTitle":"الأسنان والبزوغ","section":"بنك الأسئلة","text":"ما الوصف الأدق لكيس البزوغ؟","extra":"كيس البزوغ تجمع داخل النسج فوق السن، وغالباً يفتح تلقائياً مع البزوغ.","href":"comprehensive-exam.html"},{"id":"q-p07-q01","type":"question","page":7,"pageTitle":"بنية الأسنان","section":"بنك الأسئلة","text":"ما النسيج الذي يغطي التاج ويقاوم المؤثرات الخارجية؟","extra":"الميناء هي الطبقة الخارجية المغطية للتاج وتحميه من المؤثرات المختلفة.","href":"comprehensive-exam.html"},{"id":"q-p07-q03","type":"question","page":7,"pageTitle":"بنية الأسنان","section":"بنك الأسئلة","text":"أي عبارة صحيحة حول الميناء؟","extra":"الميناء هي الأشد صلابة بين الأنسجة السنية، بل من أقسى أنسجة الجسم.","href":"comprehensive-exam.html"},{"id":"q-p07-q04","type":"question","page":7,"pageTitle":"بنية الأسنان","section":"بنك الأسئلة","text":"ممّ يتركب الميناء كيميائياً بحسب المصدر؟","extra":"النسب الواردة للميناء هي 97% أملاح الكالسيوم و3% ماء ومواد عضوية.","href":"comprehensive-exam.html"},{"id":"q-p07-q05","type":"question","page":7,"pageTitle":"بنية الأسنان","section":"بنك الأسئلة","text":"ما الذي يشكل أساس السن والكتلة المركزية لها؟","extra":"العاج هو أساس السن ومصدر قوتها والكتلة المركزية لأنسجتها الصلبة.","href":"comprehensive-exam.html"},{"id":"q-p07-q07","type":"question","page":7,"pageTitle":"بنية الأسنان","section":"بنك الأسئلة","text":"ما اسم الألياف الموجودة في الأنابيب العاجية والتي تنقل الإحساسات الألمية؟","extra":"تسمى الألياف المذكورة ضمن الأنابيب العاجية ألياف توماز.","href":"comprehensive-exam.html"},{"id":"q-p07-q08","type":"question","page":7,"pageTitle":"بنية الأسنان","section":"بنك الأسئلة","text":"أين يوجد الملاط؟","extra":"الملاط نسيج يغلف الجذور فقط وينتهي عند العنق.","href":"comprehensive-exam.html"},{"id":"q-p07-q10","type":"question","page":7,"pageTitle":"بنية الأسنان","section":"بنك الأسئلة","text":"ما وظيفة اللب الأساسية المذكورة في المصدر؟","extra":"اللب هو النسيج الحي العصبي الوعائي، ووظيفته إعطاء الحساسية.","href":"comprehensive-exam.html"},{"id":"q-p07-q11","type":"question","page":7,"pageTitle":"بنية الأسنان","section":"بنك الأسئلة","text":"ما العاج الذي يتشكل كرد فعل دفاعي تجاه العوامل المؤذية؟","extra":"العاج الثالثي أو المرمم يتشكل استجابةً للعوامل المؤذية الخارجية.","href":"comprehensive-exam.html"},{"id":"q-p08-q01","type":"question","page":8,"pageTitle":"النسج المحيطة بالسن","section":"بنك الأسئلة","text":"ما المقصود بالنسج الداعمة للسن (Periodont)؟","extra":"النسج الداعمة للسن تضم اللثة والرباط والعظم والملاط والعناصر المساندة لها.","href":"comprehensive-exam.html"},{"id":"q-p08-q02","type":"question","page":8,"pageTitle":"النسج المحيطة بالسن","section":"بنك الأسئلة","text":"كيف يُكشف الجيب السني بحسب النص؟","extra":"الجيب السني يُكشف عندما يتجاوز عمق المسبار حول السن 3 ملم.","href":"comprehensive-exam.html"},{"id":"q-p08-q04","type":"question","page":8,"pageTitle":"النسج المحيطة بالسن","section":"بنك الأسئلة","text":"كم يبلغ عرض اللثة الحفافية تقريباً؟","extra":"ورد في النص أن عرض اللثة الحفافية نحو 1 ملم.","href":"comprehensive-exam.html"},{"id":"q-p08-q05","type":"question","page":8,"pageTitle":"النسج المحيطة بالسن","section":"بنك الأسئلة","text":"ما المجال الطبيعي المذكور لعمق الميزاب اللثوي؟","extra":"يمكن إدخال الآلة ذات الرأس الكليل بين السن واللثة لمسافة 0.5–1 ملم.","href":"comprehensive-exam.html"},{"id":"q-p08-q06","type":"question","page":8,"pageTitle":"النسج المحيطة بالسن","section":"بنك الأسئلة","text":"أي صفة من الصفات السريرية للثة الطبيعية تتعلق بشكل يشبه قشر البرتقال؟","extra":"المنظر السطحي للثة الطبيعية يبدو متجعدات ناعمة تشبه قشر البرتقال.","href":"comprehensive-exam.html"},{"id":"q-p08-q08","type":"question","page":8,"pageTitle":"النسج المحيطة بالسن","section":"بنك الأسئلة","text":"مم يتشكل الرباط السنيخي السني أساساً؟","extra":"الرباط يتكون من ألياف كثيفة تثبت السن بين الملاط والعظم.","href":"comprehensive-exam.html"},{"id":"q-p08-q09","type":"question","page":8,"pageTitle":"النسج المحيطة بالسن","section":"بنك الأسئلة","text":"ماذا قد يحدث للسن عند احتقان الرباط السنيخي السني؟","extra":"زيادة السوائل في الرباط قد ترفع السن قليلاً وتسبب ألماً عند الضغط أو الإطباق.","href":"comprehensive-exam.html"},{"id":"q-p08-q10","type":"question","page":8,"pageTitle":"النسج المحيطة بالسن","section":"بنك الأسئلة","text":"ما طبيعة العظم السنخي؟","extra":"العظم السنخي وصف في الصفحة بأنه عظم إسفنجي.","href":"comprehensive-exam.html"},{"id":"q-p08-q12","type":"question","page":8,"pageTitle":"النسج المحيطة بالسن","section":"بنك الأسئلة","text":"ما الذي يحدث للعظم السنخي بعد فقد الأسنان أو قلعها؟","extra":"يرتبط وجود العظم السنخي بوجود الأسنان، لذا يمتص ويزول بعد فقدها.","href":"comprehensive-exam.html"},{"id":"q-p09-q01","type":"question","page":9,"pageTitle":"الأمراض اللثوية","section":"بنك الأسئلة","text":"ما العاملان الأهمان المذكوران كسبب لالتهاب اللثة؟","extra":"ذكرت الصفحة أن الصفيحة الجرثومية والقلح من أهم أسباب الالتهابات اللثوية.","href":"comprehensive-exam.html"},{"id":"q-p09-q02","type":"question","page":9,"pageTitle":"الأمراض اللثوية","section":"بنك الأسئلة","text":"ماذا يعني أن يكون التهاب اللثة معمماً؟","extra":"المعمم هو الذي يحيط بجميع الأسنان.","href":"comprehensive-exam.html"},{"id":"q-p09-q04","type":"question","page":9,"pageTitle":"الأمراض اللثوية","section":"بنك الأسئلة","text":"ما العلامة التي تشكل السبب الأول للاستشارة عند المرضى في التهاب اللثة؟","extra":"النزف اللثوي ورد بوضوح كأول سبب شائع للاستشارة.","href":"comprehensive-exam.html"},{"id":"q-p09-q05","type":"question","page":9,"pageTitle":"الأمراض اللثوية","section":"بنك الأسئلة","text":"أي مما يلي يصف التهاب اللثة البسيط؟","extra":"التهاب اللثة البسيط يبقى سطحياً من دون امتداد للرباط أو العظم.","href":"comprehensive-exam.html"},{"id":"q-p09-q06","type":"question","page":9,"pageTitle":"الأمراض اللثوية","section":"بنك الأسئلة","text":"العامل الجرثومي الأساسي في التهاب اللثة الإنتاني هو:","extra":"نصت الصفحة على أن المكورات العنقودية هي العامل الجرثومي الرئيسي.","href":"comprehensive-exam.html"},{"id":"q-p09-q07","type":"question","page":9,"pageTitle":"الأمراض اللثوية","section":"بنك الأسئلة","text":"في أي الحالات يشيع التهاب اللثة الهرموني؟","extra":"التهاب اللثة الهرموني يرتبط بتبدلات الهرمونات الجنسية أو اضطرابها.","href":"comprehensive-exam.html"},{"id":"q-p09-q08","type":"question","page":9,"pageTitle":"الأمراض اللثوية","section":"بنك الأسئلة","text":"ما المرض الفيروسي المرتبط بالتهاب اللثة الفقاعي؟","extra":"التهاب اللثة الفقاعي ينجم عن الإصابة بفيروس القوباء البسيط.","href":"comprehensive-exam.html"},{"id":"q-p09-q10","type":"question","page":9,"pageTitle":"الأمراض اللثوية","section":"بنك الأسئلة","text":"ما الذي يميز التهاب اللثة حول السن؟","extra":"يمتد التهاب اللثة حول السن إلى النسج الداعمة الأعمق، ومنها الرباط والعظم.","href":"comprehensive-exam.html"},{"id":"q-p09-q11","type":"question","page":9,"pageTitle":"الأمراض اللثوية","section":"بنك الأسئلة","text":"كيف تتشكل الخراجات اللثوية الرباطية غالباً؟","extra":"احتباس القيح داخل الجيب الرباطي هو أساس تشكل الخراج.","href":"comprehensive-exam.html"},{"id":"q-p09-q12","type":"question","page":9,"pageTitle":"الأمراض اللثوية","section":"بنك الأسئلة","text":"ما الإجراء العلاجي المباشر الأبرز للخراج اللثوي الرباطي؟","extra":"المعالجة تتضمن تفجير الخراج وإخراج القيح ثم معالجة السبب.","href":"comprehensive-exam.html"},{"id":"q-p09-q13","type":"question","page":9,"pageTitle":"الأمراض اللثوية","section":"بنك الأسئلة","text":"أي دواء ذُكر مرتبطاً بالضخامة اللثوية التنسجية؟","extra":"ذكرت الصفحة مثال مرضى الصرع الذين يتناولون بديلاتين الصوديوم باستمرار.","href":"comprehensive-exam.html"},{"id":"q-p10-q01","type":"question","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"بنك الأسئلة","text":"بأي اتجاه تظهر الحركة الطبيعية للأسنان بشكل أوضح؟","extra":"الحركة الطبيعية للأسنان تكون دهليزية لسانية بشكل أوضح.","href":"comprehensive-exam.html"},{"id":"q-p10-q02","type":"question","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"بنك الأسئلة","text":"ما السبب العام للحركة المرضية للأسنان؟","extra":"الحركة المرضية تنتج عن فقدان النسج الداعمة أو تناقص الدعم العظمي.","href":"comprehensive-exam.html"},{"id":"q-p10-q04","type":"question","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"بنك الأسئلة","text":"أي مما يلي يُعد من أسباب الانحسار اللثوي؟","extra":"ذكرت الصفحة الصفيحة الجرثومية والإطباق الرضي من أهم الأسباب.","href":"comprehensive-exam.html"},{"id":"q-p10-q05","type":"question","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"بنك الأسئلة","text":"ما العامل التشريحي الذي يزيد ظهور الانحسار اللثوي؟","extra":"كلما كانت الصفيحة العظمية المغطية رقيقة زاد احتمال الانحسار.","href":"comprehensive-exam.html"},{"id":"q-p10-q06","type":"question","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"بنك الأسئلة","text":"ما هو صرير الأسنان؟","extra":"الصفحة عرّفت صرير الأسنان بأنه داء التشنج العضلي غير الطبيعي لعضلات المضغ.","href":"comprehensive-exam.html"},{"id":"q-p10-q07","type":"question","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"بنك الأسئلة","text":"أي عامل من التالي قد يتدخل في حدوث صرير الأسنان؟","extra":"ذكرت الصفحة أن الإطباق الرضي، ومنها الحشوة أو التاج المرتفع، قد يسبب الصرير.","href":"comprehensive-exam.html"},{"id":"q-p10-q08","type":"question","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"بنك الأسئلة","text":"ما الإجراء الإسعافي المذكور لكسر الحلقة المفرغة في صرير الأسنان؟","extra":"العلاج الإسعافي يكون بجهاز رفع العضة.","href":"comprehensive-exam.html"},{"id":"q-p10-q10","type":"question","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"بنك الأسئلة","text":"كيف تعرّف الصفحة الإطباق الرضي؟","extra":"الإطباق الرضي هو قوى إطباقية غير طبيعية تقع على الأسنان وتؤذي النسج الداعمة.","href":"comprehensive-exam.html"},{"id":"q-p10-q11","type":"question","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"بنك الأسئلة","text":"أي مما يلي من أسباب الإطباق الرضي؟","extra":"من الأسباب المذكورة بوضوح: المضغ وحيد الجانب.","href":"comprehensive-exam.html"},{"id":"q-p10-q12","type":"question","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"بنك الأسئلة","text":"ما الأثر الذي قد يحدث إذا ترافق الإطباق الرضي مع صفيحة جرثومية؟","extra":"من أعراض الإطباق الرضي تشكل الجيوب اللثوية عندما يترافق مع صفيحة جرثومية.","href":"comprehensive-exam.html"},{"id":"q-p10-q13","type":"question","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"بنك الأسئلة","text":"ما أهم إجراء وقائي مذكور لتجنب الإطباق الرضي بعد فقد الأسنان؟","extra":"التعويض المباشر عن الأسنان المفقودة من أهم الإجراءات الوقائية.","href":"comprehensive-exam.html"},{"id":"q-p10-q14","type":"question","page":10,"pageTitle":"اضطرابات النسج الداعمة","section":"بنك الأسئلة","text":"ما هو التواج غالباً؟","extra":"هذا هو تعريف التواج كما ورد في الصفحة.","href":"comprehensive-exam.html"},{"id":"q-p11-q01","type":"question","page":11,"pageTitle":"التهاب الفم","section":"بنك الأسئلة","text":"ما السبب الرئيسي في التهاب الفم القلاعي كما ورد في الصفحة؟","extra":"الصفحة بدأت التهاب الفم القلاعي باعتباره ناجماً عن غياب الصحة الفموية وتجمع الصفيحة وتحولها إلى قلح.","href":"comprehensive-exam.html"},{"id":"q-p11-q02","type":"question","page":11,"pageTitle":"التهاب الفم","section":"بنك الأسئلة","text":"في أي منطقة يكثر التهاب الفم القلاعي بالنسبة للقواطع السفلية؟","extra":"يكثر في اللسانية للقواطع السفلية بسبب قربها من فوهة الغدة تحت اللسان.","href":"comprehensive-exam.html"},{"id":"q-p11-q04","type":"question","page":11,"pageTitle":"التهاب الفم","section":"بنك الأسئلة","text":"أي مادة مما يلي عُدت من مواد التبغ المحرضة للالتهاب؟","extra":"الفينول ذُكر مع حمض سيان هيدريك وأكسيد الأزوت والقطران ضمن المواد المحرضة.","href":"comprehensive-exam.html"},{"id":"q-p11-q05","type":"question","page":11,"pageTitle":"التهاب الفم","section":"بنك الأسئلة","text":"ما تأثير النيكوتين المذكور في الصفحة؟","extra":"النص ذكر بوضوح أن النيكوتين ينقص إفراز اللعاب ويحرض زيادة الدوران الدموي.","href":"comprehensive-exam.html"},{"id":"q-p11-q06","type":"question","page":11,"pageTitle":"التهاب الفم","section":"بنك الأسئلة","text":"ما العلاج السببي الرئيسي لالتهاب الفم واللثة التبغي؟","extra":"المعالجة تعتمد على الإقلاع عن التدخين.","href":"comprehensive-exam.html"},{"id":"q-p11-q07","type":"question","page":11,"pageTitle":"التهاب الفم","section":"بنك الأسئلة","text":"أي مما يلي يعد عاملاً مسبباً لالتهاب الفم الناتج عن التعويضات الصناعية؟","extra":"استطالة الحواف أو وجود خشونة أو نتوءات كلها من العوامل المسببة.","href":"comprehensive-exam.html"},{"id":"q-p11-q08","type":"question","page":11,"pageTitle":"التهاب الفم","section":"بنك الأسئلة","text":"كم تدوم التقرحات الرضية الناتجة عن الجهاز عادة؟","extra":"النص ذكر أن هذه التقرحات تدوم من 7 إلى 10 أيام.","href":"comprehensive-exam.html"},{"id":"q-p11-q09","type":"question","page":11,"pageTitle":"التهاب الفم","section":"بنك الأسئلة","text":"ما الاختيار الأفضل وقائياً عندما يكون ذلك ممكناً؟","extra":"الوقاية تفضّل التعويضات الثابتة ما أمكن والهيكلية ذات الدعم السني.","href":"comprehensive-exam.html"},{"id":"q-p11-q10","type":"question","page":11,"pageTitle":"التهاب الفم","section":"بنك الأسئلة","text":"بماذا يتميز التهاب الفم الرصاصي؟","extra":"هذه هي العلامة الوصفية المميزة للفم الرصاصي.","href":"comprehensive-exam.html"},{"id":"q-p11-q11","type":"question","page":11,"pageTitle":"التهاب الفم","section":"بنك الأسئلة","text":"أي نوع من التهاب الفم المعدني قد يسبب طعماً معدنياً وتأكلاً ونخراً؟","extra":"الفم الزرنيخي يوصف بوجود طعم معدني وتبدلات سنية ومخاطية مختلفة.","href":"comprehensive-exam.html"},{"id":"q-p11-q12","type":"question","page":11,"pageTitle":"التهاب الفم","section":"بنك الأسئلة","text":"في التهاب الفم البرموتي، ما الذي يحيط باللثويات؟","extra":"الفم البرموتي يتميز بحدوث خط برموتي يحيط باللثويات.","href":"comprehensive-exam.html"},{"id":"q-p11-q13","type":"question","page":11,"pageTitle":"التهاب الفم","section":"بنك الأسئلة","text":"ما أبرز ما قد يحدث في التهاب الفم الزئبقي؟","extra":"ذكر النص التهاب اللثة التقرحي، وانتباج الشفاه واللسان، وغزارة اللعاب في الفم الزئبقي.","href":"comprehensive-exam.html"},{"id":"q-p11-q14","type":"question","page":11,"pageTitle":"التهاب الفم","section":"بنك الأسئلة","text":"بماذا يتميز التهاب الفم الفوسفوري؟","extra":"هذه هي الصفة الأهم المذكورة لهذا النوع.","href":"comprehensive-exam.html"},{"id":"q-p12-q01","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"ما القطر التقريبي للتقرح القلاعي البسيط المذكور في الصفحة؟","extra":"وصف المصدر التقرح البسيط بقطر يقارب 1–5 ملم.","href":"comprehensive-exam.html"},{"id":"q-p12-q02","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"ما المظهر اللوني النموذجي للقلاع؟","extra":"القلاع يوصف بمركز مصفر تحيط به هالة حمامية.","href":"comprehensive-exam.html"},{"id":"q-p12-q03","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"أين يمكن أن تتوضع الآفات القلاعية؟","extra":"هذه هي المواضع التي ذكرها المصدر.","href":"comprehensive-exam.html"},{"id":"q-p12-q04","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"كم تستغرق معظم حالات القلاع حتى الشفاء تقريباً؟","extra":"ذكر المصدر أن معظم الحالات تشفى بعد أسبوعين تقريباً.","href":"comprehensive-exam.html"},{"id":"q-p12-q05","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"ما الدواء المرتبط بضخامة اللثة لدى بعض مرضى الصرع؟","extra":"الديلانتين هو الدواء المذكور في هذا القسم.","href":"comprehensive-exam.html"},{"id":"q-p12-q06","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"أي وصف يناسب ضخامة اللثة الناتجة عن الديلانتين؟","extra":"تكون الضخامة قاسية وغير مؤلمة وتميل إلى شمول الأسنان الأمامية.","href":"comprehensive-exam.html"},{"id":"q-p12-q07","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"ما العامل الفطري الأهم في السلاق؟","extra":"السلاق يرتبط أساساً بالمبيضات البيض (Candida albicans).","href":"comprehensive-exam.html"},{"id":"q-p12-q08","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"أي فئة تعد أكثر عرضة للسلاق؟","extra":"ذكر المصدر الرضع الضعفاء وكبار السن ضمن الفئات الأكثر تعرضاً.","href":"comprehensive-exam.html"},{"id":"q-p12-q09","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"ما العامل الذي قد يهيئ للسلاق عند استعماله مدة طويلة؟","extra":"الاستعمال المطول للمضادات الحيوية قد يخل بالتوازن الميكروبي ويهيئ للسلاق.","href":"comprehensive-exam.html"},{"id":"q-p12-q10","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"ما الاسم الطبي الشائع للنكاف؟","extra":"النكاف هو التهاب الغدة النكفية الوبائي.","href":"comprehensive-exam.html"},{"id":"q-p12-q11","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"ما الغدة اللعابية الأكثر تأثراً بالنكاف؟","extra":"أكثر ما تتأثر به الغدة النكفية.","href":"comprehensive-exam.html"},{"id":"q-p12-q12","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"ما فترة حضانة النكاف المذكورة؟","extra":"تتراوح فترة الحضانة بين أسبوعين وثلاثة أسابيع.","href":"comprehensive-exam.html"},{"id":"q-p12-q13","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"كيف ينتقل النكاف؟","extra":"ينتقل المرض عن طريق التماس والرذاذ اللعابي.","href":"comprehensive-exam.html"},{"id":"q-p12-q14","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"أي عرض يعد نموذجياً في النكاف؟","extra":"تورم الغدة النكفية حول الأذن مع ألم المضغ من العلامات الأساسية.","href":"comprehensive-exam.html"},{"id":"q-p12-q15","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"أي مما يلي يعد من اختلاطات النكاف؟","extra":"هذه الاختلاطات الثلاثة وردت في المصدر.","href":"comprehensive-exam.html"},{"id":"q-p12-q16","type":"question","page":12,"pageTitle":"القلاع والسلاق والنكاف","section":"بنك الأسئلة","text":"ما الإجراء الوقائي الأساسي ضد النكاف؟","extra":"الوقاية تعتمد على اللقاح الحي المضعف.","href":"comprehensive-exam.html"},{"id":"q-p13-q01","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"الطلاوة تعد من أي نوع من الآفات؟","extra":"الطلاوة تذكر بوصفها من أهم الآفات ما قبل السرطانية في الفم.","href":"comprehensive-exam.html"},{"id":"q-p13-q02","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"من أكثر الفئات إصابة بالطلاوة بحسب الصفحة؟","extra":"ورد أن الطلاوة تصيب الرجال أكثر من النساء، وخاصة المتقدمين بالعمر.","href":"comprehensive-exam.html"},{"id":"q-p13-q03","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"أي من المواضع التالية من أماكن توضع الطلاوة؟","extra":"هذه من أكثر المواضع المذكورة في الصفحة.","href":"comprehensive-exam.html"},{"id":"q-p13-q04","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"كيف يوصف لون الطلاوة عادة؟","extra":"هذا هو اللون السريري الموصوف للطلاوة في النص.","href":"comprehensive-exam.html"},{"id":"q-p13-q05","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"ما أهم عامل مساعد على تشكل الطلاوة؟","extra":"التدخين هو العامل الأهم، وكثير من الآفات تتراجع بعد الإقلاع عنه.","href":"comprehensive-exam.html"},{"id":"q-p13-q06","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"أي عامل يعد أيضاً مخرشاً مهماً ويُذكر مع الطلاوة؟","extra":"الكحول يخرش الغشاء المخاطي ويعد عاملاً مهماً، خاصة مع التدخين.","href":"comprehensive-exam.html"},{"id":"q-p13-q07","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"سرطان مخاطية دهليز الفم يرتبط بشكل واضح مع:","extra":"من أهم أسبابه مضغ التبغ وما يشبهه.","href":"comprehensive-exam.html"},{"id":"q-p13-q08","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"كيف يمكن أن تبدو آفة سرطان مخاطية دهليز الفم؟","extra":"ذكرت الصفحة أنها قد تكون متقرحة مؤلمة أو ثؤلولية.","href":"comprehensive-exam.html"},{"id":"q-p13-q09","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"سرطان اللثة قد يؤدي إلى تأخر اكتشافه لأنه:","extra":"تشابهه مع التهابات اللثة قد يسبب سوء التشخيص أو التأخر في اكتشافه.","href":"comprehensive-exam.html"},{"id":"q-p13-q10","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"كم يشكل سرطان اللثة تقريباً من سرطانات داخل الفم؟","extra":"النص يذكر أنه يشكل 10–11% من سرطانات داخل الفم.","href":"comprehensive-exam.html"},{"id":"q-p13-q11","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"أي الشفتين تصاب أكثر بسرطان الشفة؟","extra":"سرطان الشفة يصيب الشفة السفلى في أغلب الحالات.","href":"comprehensive-exam.html"},{"id":"q-p13-q12","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"ما العامل الأهم في سرطان الشفة بحسب الصفحة؟","extra":"التدخين هو أهم عامل مذكور في سرطان الشفة.","href":"comprehensive-exam.html"},{"id":"q-p13-q13","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"سرطان اللسان يتوضع غالباً على:","extra":"هذا هو الموضع الأكثر شيوعاً المذكور في المادة.","href":"comprehensive-exam.html"},{"id":"q-p13-q14","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"أي من العوامل التالية له دور في سرطان اللسان؟","extra":"ذكرت الصفحة هذه العوامل مجتمعة بوصفها مهمة.","href":"comprehensive-exam.html"},{"id":"q-p13-q15","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"كيف يكون الألم في سرطان اللسان في كثير من الحالات؟","extra":"لا يترافق بالألم سريرياً إلا عندما يتعرض لالتهاب ثانوي.","href":"comprehensive-exam.html"},{"id":"q-p13-q16","type":"question","page":13,"pageTitle":"الآفات ما قبل السرطانية والسرطانية","section":"بنك الأسئلة","text":"ما المعالجة العامة المذكورة لسرطان اللسان؟","extra":"ورد أن معالجة سرطان اللسان تتم بالجراحة أو بالأشعة.","href":"comprehensive-exam.html"},{"id":"q-p14-q01","type":"question","page":14,"pageTitle":"القلح والتلونات السنية","section":"بنك الأسئلة","text":"ما هو القلح؟","extra":"هذا هو التعريف المباشر المذكور للقلح في الصفحة.","href":"comprehensive-exam.html"},{"id":"q-p14-q02","type":"question","page":14,"pageTitle":"القلح والتلونات السنية","section":"بنك الأسئلة","text":"كم تبلغ تقريباً نسبة الأملاح المعدنية في القلح؟","extra":"المادة تذكر أن القلح يحتوي على أملاح معدنية بنسبة 70–90%.","href":"comprehensive-exam.html"},{"id":"q-p14-q03","type":"question","page":14,"pageTitle":"القلح والتلونات السنية","section":"بنك الأسئلة","text":"أي مكوّن يشكل النسبة الغالبة من الأملاح المعدنية في القلح؟","extra":"فوسفات الكالسيوم هي النسبة الغالبة من الأملاح المعدنية.","href":"comprehensive-exam.html"},{"id":"q-p14-q04","type":"question","page":14,"pageTitle":"القلح والتلونات السنية","section":"بنك الأسئلة","text":"من مكونات المحتوى العضوي في القلح:","extra":"هذا هو المحتوى العضوي المذكور في الصفحة.","href":"comprehensive-exam.html"},{"id":"q-p14-q05","type":"question","page":14,"pageTitle":"القلح والتلونات السنية","section":"بنك الأسئلة","text":"أكثر أماكن توضع القلح شيوعاً هي:","extra":"هذه المناطق مرتبطة بمناطق الانصباب اللعابي ولذلك يكثر فيها القلح.","href":"comprehensive-exam.html"},{"id":"q-p14-q06","type":"question","page":14,"pageTitle":"القلح والتلونات السنية","section":"بنك الأسئلة","text":"القلح فوق اللثوي أو اللعابي يكون عادة:","extra":"هذا الوصف يخص القلح فوق اللثوي.","href":"comprehensive-exam.html"},{"id":"q-p14-q07","type":"question","page":14,"pageTitle":"القلح والتلونات السنية","section":"بنك الأسئلة","text":"القلح تحت اللثوي أو المصلي يتميز بأنه:","extra":"هذا هو الوصف الكلاسيكي للقلح تحت اللثوي.","href":"comprehensive-exam.html"},{"id":"q-p14-q08","type":"question","page":14,"pageTitle":"القلح والتلونات السنية","section":"بنك الأسئلة","text":"التلون السني هو:","extra":"التلون السني عُرّف بهذه الطريقة في الصفحة.","href":"comprehensive-exam.html"},{"id":"q-p14-q09","type":"question","page":14,"pageTitle":"القلح والتلونات السنية","section":"بنك الأسئلة","text":"أي من التالي قد يسبب التلون السني؟","extra":"كل هذه الأسباب ذُكرت بوصفها عوامل للتلون السني.","href":"comprehensive-exam.html"},{"id":"q-p14-q10","type":"question","page":14,"pageTitle":"القلح والتلونات السنية","section":"بنك الأسئلة","text":"كيف يكون لون التصبغات التبغية عادة؟","extra":"التصبغات التبغية توصف بأنها كستنائية غامقة أو سوداء.","href":"comprehensive-exam.html"},{"id":"q-p14-q11","type":"question","page":14,"pageTitle":"القلح والتلونات السنية","section":"بنك الأسئلة","text":"التلون الناتج عن التبغ يتعلق بدرجة كبيرة بـ:","extra":"ذكرت الصفحة أن التلون يتعلق بدرجة عالية بالأغشية السنية الموجودة مسبقاً.","href":"comprehensive-exam.html"},{"id":"q-p14-q12","type":"question","page":14,"pageTitle":"القلح والتلونات السنية","section":"بنك الأسئلة","text":"غبار النحاس يسبب أي لون من التلون المعدني؟","extra":"غبار النحاس يسبب تلوناً أخضر.","href":"comprehensive-exam.html"},{"id":"q-p14-q13","type":"question","page":14,"pageTitle":"القلح والتلونات السنية","section":"بنك الأسئلة","text":"أي من التالي من أمثلة التلونات المعدنية الأخرى؟","extra":"هذه الأمثلة ذُكرت حرفياً في النص.","href":"comprehensive-exam.html"},{"id":"q-p14-q14","type":"question","page":14,"pageTitle":"القلح والتلونات السنية","section":"بنك الأسئلة","text":"كيف تسهم هذه التلونات في المرض اللثوي؟","extra":"الخلاصة السريرية تؤكد أنها تشارك في إحداث مرض لثوي عبر الجراثيم وتخريش اللثة.","href":"comprehensive-exam.html"},{"id":"q-p15-q01","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"بخر الفم هو:","extra":"هذا هو التعريف المباشر لبخر الفم.","href":"comprehensive-exam.html"},{"id":"q-p15-q02","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"الفم النظيف في الحالة الطبيعية:","extra":"النص يذكر أن الفم النظيف ليس في الحالة الطبيعية أية رائحة مزعجة.","href":"comprehensive-exam.html"},{"id":"q-p15-q03","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"تنشأ الرائحة غالباً من:","extra":"هذه هي الآلية الأساسية المذكورة لحدوث البخر الفموي.","href":"comprehensive-exam.html"},{"id":"q-p15-q04","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"أي من التالي ذُكر كأمثلة للغازات المسببة للرائحة؟","extra":"هذه المركبات ذكرت صراحة ضمن الغازات الناتجة عن التفسخ.","href":"comprehensive-exam.html"},{"id":"q-p15-q05","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"جفاف الفم يؤدي إلى:","extra":"المادة تنص على أن جفاف الفم يزيد من الرائحة.","href":"comprehensive-exam.html"},{"id":"q-p15-q06","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"بخر الفم يُعد:","extra":"يجب النظر إلى البخر كعرض وكاشف عن سبب كامن.","href":"comprehensive-exam.html"},{"id":"q-p15-q07","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"تكون رائحة الفم في الصباح عادة:","extra":"وذلك بسبب نقص اللعاب أثناء النوم وتفسخ البقايا.","href":"comprehensive-exam.html"},{"id":"q-p15-q08","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"من أسباب بخر الفم العامة:","extra":"الأمراض التنفسية العلوية ذُكرت ضمن الأسباب العامة.","href":"comprehensive-exam.html"},{"id":"q-p15-q09","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"أي من التالي مثال على سبب عام مطروح مع هواء الزفير؟","extra":"هذه المواد ذكرت ضمن المواد التي تطرح عبر الهواء وتسبب رائحة.","href":"comprehensive-exam.html"},{"id":"q-p15-q10","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"من الأسباب العامة ذات الطابع الاستقلابي:","extra":"ذكر السكري ضمن الأمراض الاستقلابية المؤدية للبخر.","href":"comprehensive-exam.html"},{"id":"q-p15-q11","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"من الأسباب الفموية لبخر الفم:","extra":"هذه من أشهر الأسباب الفموية المذكورة.","href":"comprehensive-exam.html"},{"id":"q-p15-q12","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"أمراض اللثة قد تسبب بخر الفم من خلال:","extra":"القيح والانحلال الجرثومي عوامل مباشرة في الرائحة الفموية.","href":"comprehensive-exam.html"},{"id":"q-p15-q13","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"معالجة الأسباب العامة للبخر تتم:","extra":"إذا كان السبب عاماً فالمعالجة يجب أن تكون سببية لدى المختص.","href":"comprehensive-exam.html"},{"id":"q-p15-q14","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"المعالجة الفموية للبخر تشمل:","extra":"هذه هي الخطوات الأساسية لمعالجة البخر الفموي.","href":"comprehensive-exam.html"},{"id":"q-p15-q15","type":"question","page":15,"pageTitle":"بخر الفم","section":"بنك الأسئلة","text":"مضادات البخر تعمل بشكل رئيسي عبر:","extra":"هذه هي الوظيفة الجوهرية لمضادات البخر كما ورد في النص.","href":"comprehensive-exam.html"},{"id":"q-p16-q01","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"تشمل العادات الفموية السيئة في هذه الصفحة:","extra":"هذه هي المحاور الأربعة الواردة في الصفحة.","href":"comprehensive-exam.html"},{"id":"q-p16-q02","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"عادة دفع اللسان تسبب غالباً:","extra":"النص يذكر أن هذه العادة تسبب قوة دفع مستمرة غالباً على الأسنان الأمامية.","href":"comprehensive-exam.html"},{"id":"q-p16-q03","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"من نتائج الدفع اللساني:","extra":"هذه إحدى التأثيرات المهمة المذكورة لعادات دفع اللسان.","href":"comprehensive-exam.html"},{"id":"q-p16-q04","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"المعالجة الأساسية لدفع اللسان تكون بـ:","extra":"المعالجة المذكورة هي جهاز تقويمي يعلّم الطفل البلع الصحيح.","href":"comprehensive-exam.html"},{"id":"q-p16-q05","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"التنفس الفموي قد يكون ذا منشأ:","extra":"هذا هو الوصف الافتتاحي للتنفس الفموي في الصفحة.","href":"comprehensive-exam.html"},{"id":"q-p16-q06","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"من الأسباب المؤدية للتنفس الفموي:","extra":"كل هذه الأمثلة وردت ضمن الأسباب.","href":"comprehensive-exam.html"},{"id":"q-p16-q07","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"من العلامات السريرية المرافقة للتنفس الفموي:","extra":"هذه علامات سريرية مذكورة بوضوح.","href":"comprehensive-exam.html"},{"id":"q-p16-q08","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"من التأثيرات الفموية للتنفس الفموي:","extra":"جفاف الفم والنخور والالتهابات من النتائج المهمة.","href":"comprehensive-exam.html"},{"id":"q-p16-q09","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"الشاشة الفموية الواقية تستخدم من أجل:","extra":"هذا هو دورها العلاجي الرئيس كما ورد.","href":"comprehensive-exam.html"},{"id":"q-p16-q10","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"مص الإصبع هو غالباً تعويض عن:","extra":"الصفحة تربط بين اختصار الرضاعة وميل الطفل إلى مص الإصبع.","href":"comprehensive-exam.html"},{"id":"q-p16-q11","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"من الأسباب الشائعة لعادة مص الإصبع:","extra":"هذا السبب ذُكر أولاً ضمن أسباب هذه العادة.","href":"comprehensive-exam.html"},{"id":"q-p16-q12","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"من صفات سوء الإطباق الناتج عن مص الإصبع:","extra":"هذه أهم السمات الإطباقية المذكورة.","href":"comprehensive-exam.html"},{"id":"q-p16-q13","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"تعتمد شدة تأثير مص الإصبع على:","extra":"العوامل المذكورة هي المحددات الأساسية لشدة التأثير.","href":"comprehensive-exam.html"},{"id":"q-p16-q14","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"في معالجة مص الإصبع، من الخطوات المهمة:","extra":"المعالجة متعددة الجوانب وتشمل التوعية والتشجيع والوسائل التقويمية.","href":"comprehensive-exam.html"},{"id":"q-p16-q15","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"يعد التدخين في الفم:","extra":"الصفحة تصف التبغ كمصدر حرارة ونواتج احتراق مخرشة.","href":"comprehensive-exam.html"},{"id":"q-p16-q16","type":"question","page":16,"pageTitle":"العادات الفموية السيئة","section":"بنك الأسئلة","text":"من التغيرات الفموية عند المدخنين:","extra":"هذه التغيرات وردت ضمن آخر فقرة في الصفحة.","href":"comprehensive-exam.html"},{"id":"q-p17-q01","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"تتجاوز نسبة انتشار نخر الأسنان في بعض البلاد:","extra":"النص يذكر أن نسبة الانتشار قد تفوق 90% في بعض البلاد.","href":"comprehensive-exam.html"},{"id":"q-p17-q02","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"أقرب النظريات المقبولة لتفسير حدوث النخر هي:","extra":"الصفحة تذكر نظرية تكون الحموض كأقرب تفسير مقبول.","href":"comprehensive-exam.html"},{"id":"q-p17-q03","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"العوامل الأساسية اللازمة لحدوث النخر هي:","extra":"هذه هي العناصر الثلاثة الأساسية المذكورة لحدوث النخر.","href":"comprehensive-exam.html"},{"id":"q-p17-q04","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"اللويحات الجرثومية هي:","extra":"اللويحات الجرثومية هي التجمع الذي تنمو فيه الجراثيم على الأسنان.","href":"comprehensive-exam.html"},{"id":"q-p17-q05","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"أي أنواع السكريات أكثر أهمية في إحداث النخر بحسب النص؟","extra":"الصفحة تشير بوضوح إلى أهمية السكر ثنائي السكروز.","href":"comprehensive-exam.html"},{"id":"q-p17-q06","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"من المقاومة المادية للويحات الجرثومية:","extra":"النظافة الفموية تعرقل نمو اللويحات وتزيلها.","href":"comprehensive-exam.html"},{"id":"q-p17-q07","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"يزداد التأثير الضار للسكريات عندما تكون:","extra":"المنتجات اللاصقة تبقى في الفم مدة أطول، لذلك تكون أكثر خطورة.","href":"comprehensive-exam.html"},{"id":"q-p17-q08","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"تناول نفس كمية السكر على فترة زمنية أطول يؤدي إلى:","extra":"النص يذكر أن تناول كمية محدودة خلال فترة قصيرة أقل ضرراً من تناولها لفترة أطول.","href":"comprehensive-exam.html"},{"id":"q-p17-q09","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"تناول السكريات بين الوجبات يسبب:","extra":"هبوط pH المتكرر يطيل مرحلة إزالة التمعدن ويزيد النخر.","href":"comprehensive-exam.html"},{"id":"q-p17-q10","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"أي مما يلي يعد من العوامل العامة للنخر؟","extra":"هذه أمثلة مباشرة على العوامل العامة.","href":"comprehensive-exam.html"},{"id":"q-p17-q11","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"من العوامل الموضعية للنخر:","extra":"هذه العوامل تندرج تحت العوامل الموضعية.","href":"comprehensive-exam.html"},{"id":"q-p17-q12","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"تكون الأسنان الأمامية السفلية:","extra":"ذلك بسبب إحاطتها باللعاب بشكل أفضل.","href":"comprehensive-exam.html"},{"id":"q-p17-q13","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"يبدأ نخر الميناء غالباً بـ:","extra":"نخر الميناء عادةً لا يسبب أعراضاً واضحة حتى يصل إلى العاج.","href":"comprehensive-exam.html"},{"id":"q-p17-q14","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"نخر العاج يمتاز بأنه:","extra":"العاج أقل مقاومة وأكثر غنى بالمواد العضوية من الميناء.","href":"comprehensive-exam.html"},{"id":"q-p17-q15","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"من صفات التهاب اللب الناتج عن وصول النخر إليه:","extra":"هذه من الصفات السريرية الواضحة لالتهاب اللب.","href":"comprehensive-exam.html"},{"id":"q-p17-q16","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"من الممارسات الخاطئة المذكورة عند ألم السن:","extra":"النص يذكر أن ذلك لا يفيد وقد يؤذي اللثة.","href":"comprehensive-exam.html"},{"id":"q-p17-q17","type":"question","page":17,"pageTitle":"نخر الأسنان","section":"بنك الأسئلة","text":"إذا فقدت السن كمية كبيرة من النسج بعد معالجة اللب فقد تحتاج إلى:","extra":"هذا مذكور في نهاية الصفحة ضمن تدبير الأسنان الشديدة التخرب.","href":"comprehensive-exam.html"}];
